// DATA CONTOH: kunci + pembahasan versi siswa untuk 110 soal to-contoh.js. Dibuat oleh build-to.cjs.
var BAHAS = [{"k":"A","b":[["Yang ditanya","langkah nyata yang sesuai fungsi Indikator Nilai Pancasila. Fungsi itu sebagai alat ukur isi kebijakan. Kamu memegang dua tuntutan resmi sekaligus: tahapan selesai tepat waktu, dan isi rancangan dinilai dengan nilai Pancasila."],["Cara cepat","cari tindakan yang benar-benar memakai ukuran sila untuk menilai isi pasal, tanpa membuat pekerjaan keluar dari jadwal."],["Kenapa opsi lain gugur","B cuma menyalin kata dari soal “tahapan penyusunan”, dan daftar periksa bagian hukum hanya memeriksa prosedur, bukan isi. C mengukur hasil program setahun kemudian, jadi bukan langkah ketika menyusun. D konsultasi publik memang baik, tetapi itu mekanisme partisipasi, bukan fungsi indikator sebagai alat ukur. E kutipan sila di konsiderans hanya hiasan formal; isi pasalnya tidak diuji."],["Kunci","A, karena hanya A yang memakai ukuran sila untuk menilai isi setiap pasal sambil tetap di dalam jadwal tim."],["Analogi","juru masak mencicipi setiap masakan sebelum disajikan, tetapi tamu tidak dibuat menunggu lebih lama."],["Jebakan","D terasa paling “Pancasilais” karena melibatkan warga. Yang ditanya fungsi indikator, bukan cara lain yang juga baik."]]},{"k":"C","b":[["Yang ditanya","nilai yang paling tepat menjelaskan keputusan panitia, dengan ukuran indikator sila pertama dan kedua. Ada dua pihak dengan tuntutan sah: satu kelompok butuh ruang untuk menjalankan keyakinannya, kelompok lain butuh jaminan ajarannya tidak direndahkan."],["Cara cepat","keputusan panitia menjawab dua tuntutan itu sekaligus. Cari nilai yang memuat keduanya, bukan yang hanya menjelaskan jadwal."],["Kenapa opsi lain gugur","A kepatuhan menjelaskan cara panitia bekerja, bukan nilai yang mendasari isi keputusannya. B netralitas itu konsep yang mirip, tetapi berbeda; ia menjelaskan sikap tidak memihak, bukan aturan saling menghormati antarpengguna. D memancing lewat kata “jatah ruang”, dan isinya berhenti di pembagian waktu, jadi tuntutan kelompok kedua tidak tercakup. E merawat fasilitas bersama adalah akibat baik yang mungkin muncul, bukan dasar keputusan."],["Kunci","C, karena toleransi berkeadaban memuat hak berkeyakinan dan penghormatan martabat pemeluk lain."],["Analogi","dua keluarga berbagi dapur. Masing-masing boleh memasak menu sendiri, tetapi tidak boleh mengejek masakan tetangganya."],["Jebakan","B terdengar sangat ideal untuk panitia. Ingat, yang dinilai isi keputusan, bukan sikap panitia."]]},{"k":"E","b":[["Yang ditanya","wujud penerapan teladan Sidang Pertama BPUPK di forum pemuda sekarang. Teladannya punya dua sisi: anggota berani menyampaikan usulan yang berbeda, lalu bersama-sama mencari rumusan yang bisa diterima."],["Cara cepat","pindahkan dua sisi itu ke forum pemuda. Cari opsi yang memuat keberanian mengusulkan dan kerja merumuskan titik temu."],["Kenapa opsi lain gugur","A belajar sejarah sidang itu bagus, tetapi itu mengenal teladan, bukan menerapkannya. B usulan disampaikan, tetapi kerjanya berhenti pada mencatat keberatan, belum mencari titik temu. C suasana akrab adalah hasil yang diharapkan, bukan cara mencapai kesepakatan. D cuma menyalin kata dari soal “sikap bersama”; suara terbanyak memang sah, tetapi itu jalan keluar ketika titik temu tidak tercapai, bukan teladan perumusan dasar negara."],["Kunci","E, karena E memuat dua sisi teladan: usulan diajukan dengan alasan terbuka, lalu titik temu dirumuskan bersama."],["Analogi","keluarga memilih tujuan liburan. Setiap anak boleh ngotot menyebut pilihannya beserta alasannya, lalu semua mencari tempat yang bisa membuat semua senang."],["Jebakan","D terdengar demokratis dan cepat. Soal ini menanyakan teladan BPUPK, yaitu mencari rumusan bersama, bukan sekadar menghitung pendukung."]]},{"k":"B","b":[["Yang ditanya","sikap kepala sekolah dengan ukuran Pancasila sebagai ideologi terbuka. Pedoman BPIP menggambarkan Pancasila sebagai dasar yang tetap sekaligus penuntun yang dinamis. Dua guru sama-sama punya alasan sah: satu ingin teknologi baru, satu ingin arah pendidikan kebangsaan terjaga."],["Cara cepat","ideologi terbuka artinya arah dasarnya tetap, caranya boleh berubah. Cari opsi yang menerima cara baru dan tetap menyaring isi dengan nilai dasar."],["Kenapa opsi lain gugur","A cuma mengulang kata dari soal, dan “tanpa mengaktifkan fitur” jelas menolak sisi penyesuaian. C cinta produk dalam negeri itu nilai baik, tetapi ideologi terbuka tidak berarti menolak teknologi luar. D slogan di halaman pembuka hanya tempelan; isi aplikasinya tidak dinilai. E “apa adanya” berarti semua isi diterima tanpa saringan."],["Kunci","B, karena B memakai teknologi baru sambil memilah isi dengan nilai dasar bangsa."],["Analogi","kamu boleh mengganti ponsel dengan model terbaru, tetapi nomor dan kontak keluargamu tetap dipindahkan, bukan dibuang."],["Jebakan","D juga “mengadopsi plus kebangsaan”. Bedanya, D hanya menempel slogan, sedangkan B menyaring isi."]]},{"k":"D","b":[["Yang ditanya","alasan paling mendasar untuk memperbaiki kebiasaan organisasi, dengan ukuran pengertian ideologi sebagai praktik. Masalahnya jelas: Pancasila dibacakan, tetapi tidak muncul dalam keputusan."],["Cara cepat","kata “paling mendasar” meminta akar, bukan akibat. Cari alasan yang menghubungkan nilai dengan tindakan."],["Kenapa opsi lain gugur","A cuma menyalin kata dari soal dan berhenti pada pemahaman, padahal masalahnya justru di praktik. B seremoni pembukaan menjaga identitas, tetapi tidak menyentuh isi keputusan. C anggota jadi lebih aktif adalah hasil perbaikan, bukan alasan dasarnya. E kewajiban hukum itu benar, tetapi itu alasan yuridis, sedangkan soal meminta alasan ideologis."],["Kunci","D, karena D menjelaskan akar masalahnya: nilai hidup bersama baru bermakna bila mengarahkan perlakuan nyata."],["Analogi","hafal resep di luar kepala tidak membuat keluargamu kenyang. Resep itu baru berguna saat kamu benar-benar memasak."],["Jebakan","E terasa kuat karena menyebut undang-undang. Cek lensanya: yang dipakai pedoman BPIP tentang ideologi, bukan kewajiban hukum."]]},{"k":"D","b":[["Yang ditanya","pasangan langkah yang memenuhi dua sasaran resmi desa sekaligus, yaitu ibadah yang aman dan hubungan saling menghormati."],["Cara cepat","beri label setiap langkah. Langkah 1 dan 2 untuk sasaran pertama, langkah 3 untuk sasaran kedua, langkah 4 hanya administrasi. Pasangan yang benar harus mengambil satu dari sisi pertama dan langkah 3."],["Kenapa opsi lain gugur","A memakai kata sasaran pertama, dan kedua langkahnya sama-sama di sisi akses ibadah. B jadwal dan pencatatan sama-sama urusan administrasi. C ruang ibadah benar, tetapi pasangannya pencatatan, jadi sasaran kedua kosong. E forum lintas iman benar, tetapi pasangannya hanya menghasilkan laporan, bukan perlindungan ibadah."],["Kunci","D, karena hanya D yang mengambil satu langkah untuk tiap sasaran: ruang ibadah dan forum lintas iman."],["Analogi","menyiapkan arisan RT butuh dua hal, yaitu tempat berkumpul dan suasana rukun antaranggota. Buku catatan kas tidak menggantikan keduanya."],["Jebakan","A paling cepat terpilih karena kalimatnya mirip sasaran pertama. Selalu cek apakah sasaran kedua ikut terpenuhi."]]},{"k":"B","b":[["Yang ditanya","hubungan sila kedua dan sila kelima dalam kasus pelatihan kerja. Jawabannya harus menyebut keduanya dan arah hubungannya."],["Cara cepat","sila kedua menjawab “siapa yang dihormati” (setiap manusia setara martabatnya), sila kelima menjawab “apa yang dikerjakan” (hambatan diatasi supaya kesempatan nyata)."],["Kenapa opsi lain gugur","A pemerataan manfaat adalah hasil, bukan hubungan dasarnya. C arah hubungannya terbalik, seolah keadilan sosial yang melahirkan penghormatan martabat. D ketertiban program hanya urusan administrasi. E paling menggoda karena memakai kata “syarat yang sama”; padahal kasusnya menunjukkan syarat seragam justru meninggalkan warga yang terhambat."],["Kunci","B, karena martabat manusia menjadi dasar dan perluasan kesempatan bagi yang terhambat menjadi wujud keadilannya."],["Analogi","semua tamu sama-sama dihormati, tetapi tamu berkursi roda tetap dibuatkan jalur landai. Hormatnya sama, bantuannya disesuaikan."],["Jebakan","E terdengar adil karena “sama untuk semua”. Di soal keadilan sosial, perlakuan seragam belum tentu adil bila hambatannya berbeda."]]},{"k":"A","b":[["Yang ditanya","sikap usaha rintisan dengan ukuran sila ketiga tentang pengembangan kebudayaan. Dua pihak punya tuntutan sah: usaha butuh produk yang laku, penenun butuh makna motif tetap terjaga."],["Cara cepat","cari sikap yang membuat produk tetap bisa berkembang dan makna motif tetap dijaga oleh pemiliknya."],["Kenapa opsi lain gugur","B maknanya terjaga, tetapi pemasaran ditunda, jadi sisi pasar hilang. C cuma menyalin kata dari soal “selera pasar”, dan makna motif hanya jadi label di kemasan. D royalti itu adil secara ekonomi, tetapi membayar tidak sama dengan menjaga makna. E cerita asal-usul dipakai untuk promosi; desainnya sendiri tidak dijaga."],["Kunci","A, karena desain baru dirancang bersama pemilik tradisi dengan batas pakem yang disepakati."],["Analogi","kamu boleh mengaransemen ulang lagu daerah jadi versi modern, asal liriknya tidak diubah dan kamu bertanya dulu kepada pemilik lagunya."],["Jebakan","D terasa paling “bertanggung jawab” karena ada uang untuk desa. Soal ini menanyakan makna budaya, dan makna tidak terjaga hanya karena dibayar."]]},{"k":"B","b":[["Yang ditanya","langkah nyata yang sesuai kedudukan Pancasila sebagai norma dasar. Soal sudah memberi petunjuk: Pancasila bukan hanya dikutip, tetapi menjadi ukuran isi peraturan."],["Cara cepat","“ukuran” berarti sesuatu dipakai untuk menguji. Cari tindakan yang menguji isi raperda terhadap dasar tertinggi."],["Kenapa opsi lain gugur","A cuma menyalin kata dari soal “rumusan” dan “Pembukaan UUD”, tetapi berhenti pada kutipan, persis hal yang disebut “bukan sekadar” di soal. C sosialisasi baru terjadi setelah disahkan. D membandingkan dengan perda lain itu harmonisasi setingkat, bukan uji terhadap norma dasar. E seremoni hanya formalitas."],["Kunci","B, karena B menjadikan dasar tertinggi sebagai ukuran untuk menguji isi pasal sebelum berlaku."],["Analogi","semua bangunan di kompleks harus mengikuti denah induk. Memasang foto denah di pintu masuk tidak cukup; setiap rumah dicek apakah sesuai denah."],["Jebakan","A terasa “paling Pancasila” karena menyebut Pembukaan UUD. Soal sudah menolak cara itu lewat frasa “bukan sekadar rumusan yang dikutip”."]]},{"k":"C","b":[["Yang ditanya","penerapan proses Sidang Kedua BPUPK di OSIS. Proses itu punya dua sisi: usulan yang berbeda dibahas dan diuji, lalu hasilnya disusun menjadi satu rancangan tertulis."],["Cara cepat","cari opsi yang berakhir pada satu naskah bersama, dan naskah itu lahir dari pengujian usulan yang berbeda."],["Kenapa opsi lain gugur","A arsip perdebatan berguna, tetapi tidak menghasilkan naskah. B usulan dipertajam, tetapi berhenti sebelum dibahas bersama. D suara terbanyak memilih satu usulan dan membuang yang lain, bukan merangkai. E cuma menyalin kata dari soal “usulan” dan “aturan kelas”, tetapi hasil akhirnya tetap aturan terpisah per kelas."],["Kunci","C, karena C menguji usulan yang bertentangan lalu merangkainya menjadi satu naskah, sama dengan pola rancangan UUD."],["Analogi","kelompok tugas yang anggotanya membawa draf berbeda. Draf-draf itu dibandingkan dan diperbaiki sampai jadi satu laporan, bukan dipilih salah satu lewat suara."],["Jebakan","D dan C sama-sama berakhir pada satu aturan. Bedanya, D membuang usulan kalah, sedangkan C merangkai."]]},{"k":"C","b":[["Yang ditanya","makna persatuan menurut sila ketiga, terlihat pada rancangan festival yang mana. Dua sekolah punya keinginan sah: kekhasan daerah tetap tampil, dan peserta merasa satu bangsa."],["Cara cepat","persatuan Indonesia itu “beragam tetapi satu”. Cari rancangan yang ragamnya tetap terlihat dan arahnya ke rasa kebangsaan."],["Kenapa opsi lain gugur","A kompetisi menjawab tujuan lomba, bukan makna persatuan. B cuma menyalin kata dari soal “tradisinya yang khas”, dan isinya hanya panggung per daerah tanpa arah kebangsaan. D paling halus: kolaborasi terdengar bersatu, tetapi “meleburkan” menghapus kekhasan; itu penyatuan bentuk, bukan persatuan. E pengetahuan tentang keragaman adalah hasil, belum rasa memiliki."],["Kunci","C, karena ragam karya daerah tetap tampil dan diarahkan pada kebanggaan sebagai warga Indonesia."],["Analogi","paduan suara terdengar indah karena sopran, alto, tenor, dan bas tetap berbeda tetapi menyanyikan lagu yang sama. Kalau semua disuruh bersuara sama, itu bukan harmoni."],["Jebakan","D terasa paling “bersatu”. Kata kuncinya “meleburkan”: kekhasan hilang, jadi sisi pertama gugur."]]},{"k":"E","b":[["Yang ditanya","kebijakan platform yang sesuai prinsip demokrasi ekonomi Pasal 33 ayat (4). Ada dua sasaran resmi: transaksi naik, dan perekonomian tumbuh secara efisien sekaligus berkeadilan."],["Cara cepat","“efisiensi berkeadilan” berarti pasar tetap jalan, tetapi pelaku lemah dibantu supaya ikut tumbuh. Cari opsi yang memuat keduanya."],["Kenapa opsi lain gugur","A biaya seragam terlihat adil, tetapi pelaku yang tertinggal tetap tertinggal. B promosi ada, tetapi dukungan teknis dilepas ke pasar. C etalase khusus hanya fasilitas formal, dan “tanpa pendampingan” menutup sisi pemerataan. D cuma menyalin kata dari soal “transaksi”, dan jumlah transaksi hanya keluaran, bukan pemerataan."],["Kunci","E, karena kanal penjualan menjawab sisi efisiensi, sedangkan pelatihan dan modal menjawab sisi berkeadilan."],["Analogi","lomba lari antarkampung terasa adil kalau semua peserta dapat sepatu dan latihan dulu, bukan hanya garis start yang sama."],["Jebakan","A memakai kata “seragam dan transparan” yang terdengar adil. Ingat, prinsipnya kebersamaan dan efisiensi berkeadilan, bukan hanya perlakuan sama."]]},{"k":"D","b":[["Yang ditanya","alasan paling mendasar bagi cara musyawarah itu, dengan ukuran sila keempat. Soal memberi dua sisi: suara rakyat didengar, dan keputusannya diarahkan ke kesejahteraan bersama."],["Cara cepat","sila keempat memuat dua kata penting, yaitu “kerakyatan” dan “hikmat kebijaksanaan”. Alasan yang mendasar harus menyentuh asal kekuasaan (rakyat) dan arah keputusan (keadilan)."],["Kenapa opsi lain gugur","A suara terbanyak memang sah, tetapi itu demokrasi mayoritas, bukan musyawarah yang dipimpin hikmat kebijaksanaan. B tertib bicara hanya prosedur. C penerimaan sosial adalah dampak baik, bukan dasarnya. E cuma menyalin kata dari soal “warga” dan “program”, dan menjadikan kesepakatan sekadar alat meredam penolakan."],["Kunci","D, karena D menjelaskan asal keputusan (kedaulatan publik) dan arahnya (keadilan sosial) dalam satu alasan."],["Analogi","keluarga yang berembuk soal uang belanja. Semua anggota didengar, tetapi keputusannya tetap diarahkan ke kebutuhan seluruh keluarga, bukan ke yang paling keras bersuara."],["Jebakan","C dan E terdengar seperti alasan, padahal keduanya akibat. Kata “paling mendasar” selalu meminta akar."]]},{"k":"A","b":[["Yang ditanya","kombinasi sasaran yang memenuhi dua ketentuan sekaligus, dengan ukuran indikator sila kelima. Ketentuannya: kesempatan hidup layak diperluas, dan kemajuan ekonomi tetap berkelanjutan."],["Cara cepat","beri label tiap sasaran. Sasaran 1, 2, 3 di sisi kesempatan hidup layak; sasaran 4 di sisi keberlanjutan; sasaran 5 hanya pelaporan. Pasangan yang benar wajib memuat sasaran 4 dan satu sasaran yang menyangkut kemajuan ekonomi."],["Kenapa opsi lain gugur","B pendidikan dan kesehatan sama-sama di sisi pertama. C kepercayaan warga adalah efek publikasi, bukan isi ketentuan. D lingkungan benar, tetapi pasangannya hanya pelaporan, jadi sisi kesempatan kosong. E paling menggoda karena cuma menyalin frasa dari soal “kesempatan hidup layak”, padahal keduanya di sisi yang sama."],["Kunci","A, karena kesempatan usaha menjawab sisi ekonomi dan hidup layak, sedangkan perlindungan lingkungan membuat kemajuan itu berkelanjutan."],["Analogi","petani yang ingin panen besar tahun ini tetapi tetap menjaga kesuburan tanah untuk musim berikutnya."],["Jebakan","E cuma menyalin kalimat dari soal hampir utuh. Kalimat yang mirip soal justru sering hanya menutup satu sisi."]]},{"k":"B","b":[["Yang ditanya","penerapan makna pidato 1 Juni 1945 dalam pekerjaan tim desa. Makna pidato itu adalah lima prinsip diusulkan sebagai dasar untuk menata negara. Soal juga menolak cara yang hanya berupa peringatan."],["Cara cepat","“dasar untuk menata” berarti prinsip dipakai sebagai ukuran ketika memutuskan. Cari opsi yang menjadikan sila sebagai alat menilai rencana."],["Kenapa opsi lain gugur","A kebanggaan warga adalah efek peringatan, sedangkan soal meminta teladan dalam pekerjaan. C cuma menyalin kata dari soal “pidato 1 Juni 1945”, tetapi arsip hanya menyimpan. D paling halus: memakai prinsip dari pidato, tetapi hanya satu prinsip dan hanya sebagai tema. E kajian sejarah rumusan itu belajar, bukan menerapkan."],["Kunci","B, karena B menjadikan kelima sila sebagai ukuran untuk menilai usulan sebelum ditetapkan, sama dengan fungsi dasar negara."],["Analogi","fondasi rumah tidak dipajang di ruang tamu. Fondasi menentukan di mana dinding boleh berdiri."],["Jebakan","D terdengar paling dekat dengan pidato karena menyebut “prinsip kebangsaan”. Cek dua hal: jumlah prinsipnya cuma satu, dan fungsinya hanya tema."]]},{"k":"B","b":[["Yang ditanya","hubungan Pancasila dan UUD NRI Tahun 1945. Jawabannya wajib menyebut keduanya dan menunjukkan arah hubungannya, bukan sekadar menyandingkan."],["Cara cepat","tes kata kerja penghubungnya. Opsi yang memakai “sedangkan” hanya menjejerkan dua hal; opsi yang memakai kata kerja seperti “mendasari” benar-benar menghubungkan."],["Kenapa opsi lain gugur","A hanya bicara konstitusi, jadi tidak ada hubungan. C dua fungsi yang benar dijejerkan, tetapi tidak dihubungkan. D membatasi Pancasila pada perilaku sehari-hari, padahal Pancasila juga dasar bangunan negara. E paling menggoda karena labelnya benar, tetapi hanya dua label yang dijejerkan."],["Kunci","B, karena nilai Pancasila menjadi dasar lahirnya norma UUD; urutan dan beda fungsinya terjawab sekaligus."],["Analogi","resep dan masakan. Resep menentukan isi masakan, tetapi resep bukan masakannya. Keduanya berhubungan, tetapi tidak sama."],["Jebakan","C, D, dan E semuanya berpola “X begini, sedangkan Y begitu”. Pola itu menjejerkan, bukan menghubungkan."]]},{"k":"B","b":[["Yang ditanya","wujud gotong royong dengan ukuran asas kerja dan tanggung jawab bersama. Dua kelompok warga sama-sama benar: satu ingin kerja cepat, satu mengingatkan bahwa perawatan sesudahnya juga tanggung jawab bersama."],["Cara cepat","asas gotong royong punya dua sisi, yaitu bekerja bersama dan menanggung hasilnya bersama. Cari opsi yang tidak berhenti saat pekerjaan selesai."],["Kenapa opsi lain gugur","A memakai tuntutan pihak pertama dan berhenti “dalam sehari”, jadi perawatan tidak tercakup. C rasa akrab adalah efek, bukan tindakan menanggung hasil. D sumbangan dana itu dukungan, bukan kerja dan tanggung jawab bersama. E syukuran hanya seremoni."],["Kunci","B, karena renovasi dikerjakan bersama dan perawatannya dibagi bergiliran sesudahnya."],["Analogi","piket kelas tidak selesai saat kelas dicat bersama; besok-besok tetap ada jadwal menyapu supaya kelas tidak kotor lagi."],["Jebakan","A paling cepat dipilih karena terlihat paling “gotong royong”. Soal sudah memberi petunjuk: pos lama rusak karena tidak dirawat."]]},{"k":"C","b":[["Yang ditanya","pengaturan pemerintah desa dengan ukuran indikator sila pertama. Dua pihak punya tuntutan sah: kelompok besar butuh kepastian jam, kelompok kecil butuh kesempatan yang setara."],["Cara cepat","kalau dua tuntutan sah bertemu, cari mekanisme yang mempertemukan keduanya secara terbuka, bukan yang memenangkan satu pihak."],["Kenapa opsi lain gugur","A urutan permohonan tanpa koordinasi membuat benturan dibiarkan. B membagi sama terlihat adil, tetapi benturan diserahkan ke pengguna sendiri. D mendahulukan yang terbesar memakai ukuran jumlah, padahal hak beribadah tidak bergantung pada besar kelompok. E kebiasaan pengelola bukan mekanisme yang disepakati."],["Kunci","C, karena alokasi disusun terbuka melalui dialog dan disepakati bersama, sehingga kedua tuntutan dibahas di satu meja."],["Analogi","tiga keluarga berbagi satu mobil. Jalan terbaik bukan siapa yang paling banyak anggotanya, tetapi duduk bersama menyusun jadwal yang disepakati."],["Jebakan","D terdengar adil karena ada “waktu pengganti”. Tetapi urutannya tetap ditentukan oleh jumlah, bukan kesepakatan."]]},{"k":"E","b":[["Yang ditanya","sikap yang meneladani Sidang Kedua BPUPK. Teladannya dua sisi: banyak bidang dibahas, dan semuanya ditimbang untuk kepentingan negara, bukan kepentingan kelompok."],["Cara cepat","pindahkan dua sisi itu ke forum kabupaten. Cari sikap yang membandingkan banyak bidang lalu memilih demi kepentingan bersama."],["Kenapa opsi lain gugur","A cuma menyalin kata dari soal “sektor”; agenda diperluas, tetapi tidak ada arah memilih. B dokumentasi hanya tata kelola. C rapat lancar dan tepat jadwal adalah hasil prosedural. D paling menggoda: mewakili dinas itu memang tugasmu, tetapi “mandat dinas sendiri” membatasi orientasi pada satu sektor."],["Kunci","E, karena E menimbang usulan antarbidang lalu mendahulukan pilihan bagi kemaslahatan bersama."],["Analogi","rapat keluarga soal uang bulanan. Setiap anggota boleh menyampaikan kebutuhan, tetapi keputusan diambil untuk kepentingan seluruh rumah, bukan kamar masing-masing."],["Jebakan","D terlihat profesional dan sopan. Yang ditanya keteladanan BPUPK, yaitu orientasi pada kepentingan bersama, bukan kesetiaan pada mandat sektor."]]},{"k":"A","b":[["Yang ditanya","kebijakan yang adil menurut indikator sila kedua dan kelima. Ada dua ketentuan resmi: syarat akademik sama, dan pendaftaran terjangkau di setiap wilayah. Masalahnya ada di jalur pendaftaran, bukan di syaratnya."],["Cara cepat","tanyakan dulu “hambatannya di mana?”. Hambatannya sinyal, jadi yang diubah jalurnya, bukan standarnya."],["Kenapa opsi lain gugur","B tenggat lebih panjang tidak menolong kalau jalurnya tetap daring. C cuma menyalin kata dari soal “syarat akademik”; menurunkan syarat itu kebijakan afirmasi, tetapi melanggar ketentuan pertama dan tidak menyentuh hambatannya. D bantuan teknis daring tetap butuh sinyal, dan “satu kanal resmi” mempertahankan hambatan. E kuota mengatur pembagian kursi, bukan cara mendaftar."],["Kunci","A, karena jalur luring membuka akses, sedangkan ukuran kelayakannya tetap setara bagi semua."],["Analogi","ujian SIM tetap sama untuk semua orang, tetapi kantornya dibuka keliling ke desa yang jauh."],["Jebakan","C terasa paling berpihak pada pelamar terpencil. Tetapi masalah mereka sinyal, bukan kemampuan akademik."]]},{"k":"E","b":[["Yang ditanya","makna fungsi pemersatu Pancasila yang paling mendasar. Soal sudah memberi dua sisi: keragaman diterima, lalu diarahkan ke cita-cita bersama."],["Cara cepat","kata “makna” meminta konsep, bukan kegiatan. Coret dulu opsi yang berupa kegiatan atau manfaat, lalu cari yang memuat “beragam” dan “diarahkan”."],["Kenapa opsi lain gugur","A menyalin isi soal dan berupa kegiatan, bukan makna. B berkurangnya prasangka adalah manfaat. C jaringan organisasi itu kohesi kelembagaan, bukan fungsi nilai pemersatu. D identitas dijaga “secara mandiri”, jadi arah bersamanya hilang."],["Kunci","E, karena keragaman dipertemukan dalam nilai yang sama lalu digerakkan ke kemajuan Indonesia."],["Analogi","jari-jari roda sepeda berbeda arah, tetapi semuanya bertemu di poros yang sama sehingga roda bisa berputar maju."],["Jebakan","A terasa benar karena isinya persis yang terjadi di forum. Yang ditanya makna, bukan kejadiannya."]]},{"k":"A","b":[["Yang ditanya","mekanisme yang sesuai indikator sila keempat. Kamu menghadapi tekanan yang sah, yaitu tenggat dari wali kota, dan ketentuan bahwa aspirasi harus diolah secara bertanggung jawab."],["Cara cepat","“diolah secara bertanggung jawab” punya tiga tanda: masukan didengar, ditanggapi, dan alasan keputusan dijelaskan. Cari opsi yang memuat ketiganya dan tetap muat dalam jadwal."],["Kenapa opsi lain gugur","B masukan dibuka, tetapi pengolahannya diserahkan ke tim teknis tanpa tanggapan. C jajak pendapat cepat memakai suara terbanyak, bukan penimbangan alasan. D perwakilan diundang, tetapi keputusan ditetapkan sebelum tanggapan terbit, jadi kehadiran mereka hanya formal. E cuma menyalin kata dari soal “aspirasi”, tetapi alasan akhirnya tidak dijelaskan."],["Kunci","A, karena konsultasi terjadwal muat dalam tenggat, sedangkan tanggapan dan alasan pilihan akhir dipublikasikan."],["Analogi","guru yang menerima protes nilai dari siswa. Guru menjadwalkan waktu, menjawab setiap protes, lalu menjelaskan alasan nilai akhirnya."],["Jebakan","C terlihat cepat dan demokratis, cocok untuk tenggat. Kecepatan bukan ukurannya; ukurannya pengolahan aspirasi."]]},{"k":"B","b":[["Yang ditanya","ciri pembeda musyawarah dari pemungutan suara, dengan ukuran indikator sila keempat. Dua kelompok anggota sama-sama sah: satu ingin cepat lewat voting, satu ingin alasan dibahas."],["Cara cepat","kata “membedakan” meminta ciri yang tidak dimiliki voting. Waktu bicara yang sama juga ada di voting, jadi bukan pembeda."],["Kenapa opsi lain gugur","A cuma menyalin frasa dari soal tentang waktu bicara, dan itu ada di kedua cara. C menerima hasil mayoritas justru ciri voting. D catatan evaluasi adalah manfaat lanjutan. E prosedur rapi juga ada di voting."],["Kunci","B, karena hanya musyawarah yang mengolah pandangan sampai menjadi kesepakatan yang dijalankan dengan itikad baik."],["Analogi","memilih menu makan bersama. Voting cukup angkat tangan; musyawarah menanyakan dulu alasan tiap orang, misalnya ada yang alergi, lalu mencari menu yang bisa diterima semua."],["Jebakan","A paling dekat dengan isi soal. Ingat, soal “membedakan” menuntut ciri yang hanya dimiliki satu pihak."]]},{"k":"C","b":[["Yang ditanya","pasangan kegiatan yang memenuhi dua isi panduan, dengan ukuran indikator sila ketiga: bangga pada budaya daerah, dan mendahulukan kepentingan bangsa di atas golongan."],["Cara cepat","beri label. Kegiatan 1 dan 2 di sisi budaya, kegiatan 3 dan 5 di sisi kepentingan bangsa, kegiatan 4 justru kepentingan golongan. Pasangan yang benar mengambil satu dari tiap sisi dan tidak memuat kegiatan 4."],["Kenapa opsi lain gugur","A dua-duanya identitas kelompok, dan kegiatan 4 kepentingan golongan. B dua-duanya di sisi nasional, budaya daerah kosong. D cuma menyalin kata dari soal “budaya daerah”, tetapi dua-duanya di sisi budaya. E kegiatan 4 adalah promosi golongan, jadi gabungannya dengan agenda nasional semu."],["Kunci","C, karena pertukaran budaya merawat keragaman dan aksi bantuan bencana lintas organisasi mendahulukan kepentingan bersama."],["Analogi","tim sepak bola daerah boleh bangga dengan seragamnya, tetapi saat bencana mereka turun bersama tim lain membantu korban."],["Jebakan","E memakai kata “agenda nasional” yang terdengar benar. Cek kegiatan 4: itu kepentingan golongan, jadi pasangan itu gugur."]]},{"k":"D","b":[["Yang ditanya","penerapan pelajaran dari perumusan dasar negara 1945. Soal menulis dua sisinya dengan jelas: gagasan pokok dipertahankan, rumusan disempurnakan agar diterima semua kelompok."],["Cara cepat","cari opsi yang memegang inti dan sekaligus mengubah bunyinya lewat dialog."],["Kenapa opsi lain gugur","A cuma menyalin kata dari soal “anggaran dasar”, dan “tanpa perubahan redaksi” menolak sisi penyempurnaan. B mengikuti kelompok terbesar berbeda dari rumusan yang diterima semua. C membahas lebih lama membantu saling paham, tetapi tidak menentukan apa yang dipertahankan. E usulan hanya dicatat, lalu penyelarasan diserahkan ke satu orang."],["Kunci","D, karena tujuan dasar perkumpulan dipegang, sedangkan redaksinya disempurnakan lewat dialog antaranggota."],["Analogi","lagu sekolah diaransemen ulang supaya cocok dinyanyikan siswa baru, tetapi pesan dan nadanya tetap."],["Jebakan","A terdengar setia pada sejarah karena “mempertahankan”. Sejarah perumusan justru menunjukkan rumusan boleh berubah selama gagasan pokoknya terjaga."]]},{"k":"B","b":[["Yang ditanya","tindakan yang menunjukkan Pancasila dipakai sebagai tolok ukur kebijakan. Panduan memberi dua syarat: bantuan tepat sasaran, dan siswa tidak dipermalukan atau dirugikan oleh cara seleksi."],["Cara cepat","Pancasila menilai hasil kebijakan (adil, sila kelima) dan cara kebijakan memperlakukan orang (bermartabat, sila kedua). Cari opsi yang mengurus keduanya."],["Kenapa opsi lain gugur","A cuma menyalin kata dari soal “tepat sasaran”, dan kata “mengutamakan” menunjukkan hanya ketepatan yang diurus. C dua langkah, tetapi keduanya administrasi; tanda tangan orang tua tidak memeriksa apakah hasil aplikasi benar. D kenaikan nilai adalah akibat bantuan, bukan cara memilih penerima. E paling menggoda karena menyebut “dirugikan”, tetapi pengaduan menunggu kerugian terjadi dulu."],["Kunci","B, karena memeriksa ulang hasil mesin menjaga ketepatan, dan merahasiakan nama penerima menjaga siswa dari rasa malu."],["Analogi","wali kelas yang membagikan rapor. Nilainya harus dicek benar, dan rapor diberikan satu per satu, tidak dibacakan di depan kelas."],["Jebakan","E terdengar peduli karena ada saluran pengaduan. Cek waktunya: ketentuan meminta pencegahan, pengaduan adalah pemulihan."]]},{"k":"E","b":[["Yang ditanya","penerapan rumusan tujuan negara ketika karang taruna harus memilih program dengan dana terbatas. Sisi dulu: alinea keempat menyebut tujuan seperti kesejahteraan umum dan kecerdasan bangsa. Sisi kini: keputusan memilih program."],["Cara cepat","“menerapkan” dalam keputusan berarti tujuan itu dipakai sebagai ukuran untuk menimbang. Cari opsi yang menjadikan isi tujuan negara alat menilai."],["Kenapa opsi lain gugur","A mengenalkan isi naskah itu sosialisasi, keputusannya belum tersentuh. B ukurannya hanya cepat selesai. C paling menggoda karena cuma menyalin kata dari soal “tujuan negara”, padahal kutipan di proposal hanya hiasan dokumen. D suara terbanyak sah untuk mengambil keputusan, tetapi itu ukuran cara memutus, bukan ukuran isi tujuan negara."],["Kunci","E, karena taraf hidup dan pendidikan warga adalah bentuk nyata kesejahteraan umum dan kecerdasan bangsa, lalu dipakai untuk menilai tiap rencana."],["Analogi","keluarga dengan uang terbatas memakai tujuan “anak sehat dan sekolah lancar” untuk memilih belanja, bukan menempel tulisan itu di kulkas."],["Jebakan","C dan E sama-sama dua komponen. Bedakan: C menulis tujuan, E memakai tujuan."]]},{"k":"C","b":[["Yang ditanya","pasangan kegiatan yang mencerminkan sila keempat dan kelima. Dua sisinya: suara warga sekolah masuk ke keputusan, dan manfaat dibagi adil."],["Cara cepat","beri label tiap kegiatan. Kegiatan 2 = sisi suara. Kegiatan 5 = sisi pembagian adil. Kegiatan 3 dan 4 bermanfaat, tetapi soal bilang manfaat saja belum cukup. Kegiatan 1 dan 6 tidak masuk dua sisi itu."],["Kenapa opsi lain gugur","A sudah memuat kegiatan 2, tetapi pasangannya pameran budaya, jadi sisi keadilan kosong. B cuma menyalin kata dari soal “manfaat”, padahal soal justru menolak ukuran “sekadar bermanfaat”. D kebanggaan dan disiplin baik, tetapi tidak menyentuh dua sisi. E paling menggoda karena memuat kegiatan 5, tetapi pasangannya bantuan bencana, jadi keduanya di sisi pembagian."],["Kunci","C, karena forum lintas kelas membuat siswa ikut memutus, dan fasilitas yang didahulukan bagi yang kekurangan membuat pembagian adil."],["Analogi","memasak untuk satu rumah. Menu ditanyakan ke semua penghuni, lalu porsi lebih besar diberikan ke yang sedang sakit."],["Jebakan","A dan E sama-sama memuat satu kegiatan yang benar. Cek pasangannya, jangan berhenti di satu nomor."]]},{"k":"D","b":[["Yang ditanya","alasan paling mendasar kenapa peraturan perlu ditinjau ulang, dengan ukuran sila kedua dan kelima. Dua sisinya: prosedurnya sah, dan akibatnya adil bagi setiap warga."],["Cara cepat","kata “karena” meminta dasar, bukan langkah dan bukan akibat. Dasar yang kuat menjelaskan kenapa aturan yang sah prosedurnya tetap bisa kurang layak."],["Kenapa opsi lain gugur","A cuma menyalin kata dari soal “prosedur resmi” dan hanya membela sisi prosedur, padahal sisi itu sudah terpenuhi. B menghimpun masukan itu langkah perbaikan, jadi yang dijawab langkah, bukan alasan. C kepercayaan warga adalah efek. E paling menggoda karena berbunyi dua komponen, tetapi sah dan tertulis jelas dua-duanya urusan prosedur."],["Kunci","D, karena aturan layak ditaati bila caranya benar dan hasilnya setara; peraturan ini baru memenuhi yang pertama."],["Analogi","wasit yang memimpin sesuai buku aturan, tetapi lapangannya miring ke satu sisi. Pertandingan sah, tetapi belum adil sampai lapangan diratakan."],["Jebakan","E memakai pola “A dan B”. Pola dua komponen tidak otomatis benar; cek apakah kedua komponen benar-benar mewakili dua sisi yang berbeda."]]},{"k":"A","b":[["Yang ditanya","langkah yang menunjukkan Pembukaan dipakai sebagai pedoman panitia. Dua tuntutan anggota sama-sama sah: isinya diingat, dan isinya memengaruhi program."],["Cara cepat","pedoman berarti isi naskah menentukan arah kerja. Cari opsi yang memindahkan isi Pembukaan ke dalam program, dan tetap membuat anggota mengenal isinya."],["Kenapa opsi lain gugur","B cuma menyalin kata dari soal “dibacakan” dan “pertemuan”; anggota jadi hafal, tetapi program tetap sama. C rasa bangga adalah akibat, bukan langkah. D mencatat dan menempel tampak dua langkah, tetapi hasilnya hanya pajangan. E mengundang guru itu baik, tetapi menjelaskan isi Pembukaan adalah peran guru, sedangkan tugas panitia menyusun program."],["Kunci","A, karena sasaran kegiatan diturunkan dari alinea keempat, lalu dibahas di rapat sehingga isinya dikenal sekaligus dipakai."],["Analogi","resep masakan. Membacanya keras-keras tidak membuat sup jadi; resep berguna ketika takarannya dipakai saat memasak."],["Jebakan","B persis mengikuti tuntutan kelompok pertama. Opsi yang hanya mengabulkan satu pihak biasanya cuma menjawab separuh."]]},{"k":"A","b":[["Yang ditanya","Pernyataan mana yang membuat kita makin yakin bahwa kecelakaan malam turun karena lampu baru, bukan karena hal lain."],["Kalimat kunci","lampu penerangan baru itulah yang menurunkan kecelakaan pada malam hari"],["Cara cepat","Kesimpulan sebab-akibat menjadi kuat kalau penyebab lain disingkirkan. Cari opsi yang membuat lampu tinggal sendirian sebagai tersangka."],["Langkah","Soal hanya membandingkan dua tahun: 24 kecelakaan sebelum lampu dipasang, 9 sesudahnya. Angka itu bisa turun karena banyak hal. Misalnya kendaraan yang lewat malam hari jauh berkurang. Jalan yang sepi wajar jarang kecelakaan, ada lampu baru atau tidak. Opsi A menutup kemungkinan itu: jumlah kendaraan malam sama besar di kedua tahun. Bedanya tinggal lampu, dan kesimpulan kepala dinas makin kokoh."],["Kenapa opsi lain gugur",{"B":"Mahal atau murahnya lampu tidak menjelaskan kenapa kecelakaan turun. Topiknya nyambung, tetapi hubungan sebabnya tidak tersentuh.","C":"Coba baca lagi soalnya. Penurunan dari 24 ke 9 sudah tertulis. Opsi C cuma mengulang fakta itu dengan kata lain, jadi tidak menambah alasan apa pun.","D":"Banyaknya truk adalah ciri jalan itu, sebelum maupun sesudah lampu dipasang. Keterangan ini tidak membedakan kedua tahun.","E":"Opsi ini malah berbalik arah. Kalau kecelakaan siang ikut turun hampir sama, padahal siang hari tidak butuh lampu, berarti ada penyebab lain yang bekerja. Kesimpulan kepala dinas justru melemah."}],["Kunci","A, karena dengan jumlah kendaraan malam yang sama, penurunan kecelakaan tidak bisa lagi dijelaskan oleh jalan yang lebih sepi."],["Analogi","Kamu ganti merek pupuk, lalu panen tomat naik. Supaya yakin pupuknya yang berjasa, kamu perlu tahu cuaca dan banyak tanamannya sama dengan musim lalu."],["Jebakan","Wajar kalau kamu tergoda opsi C, karena bunyinya paling sejalan dengan kesimpulan. Pernyataan yang sekadar setuju belum tentu memperkuat. Yang memperkuat adalah pernyataan yang menyingkirkan penyebab lain."]]},{"k":"D","b":[["Yang ditanya","Kesimpulan apa yang pasti benar kalau kedua premis dianggap benar."],["Kalimat kunci","lulus uji renang 400 meter"],["Cara cepat","Frasa yang muncul di kedua premis adalah penghubungnya. Susun rantai: penyelam SAR, lalu lulus uji renang, lalu tidak berusia di bawah 18 tahun. Ujung ke ujung: tidak ada penyelam SAR yang berusia di bawah 18 tahun."],["Langkah","Bayangkan tiga lingkaran. Lingkaran penyelam SAR berada utuh di dalam lingkaran peserta yang lulus uji renang (P1). Lingkaran peserta yang lulus itu sama sekali tidak bersentuhan dengan lingkaran orang di bawah 18 tahun (P2). Penyelam SAR terkurung di dalam lingkaran peserta lulus, sehingga mereka juga tidak mungkin menyentuh lingkaran di bawah 18 tahun. Itulah bunyi opsi D."],["Kenapa opsi lain gugur",{"A":"P1 bilang semua penyelam pasti lulus, bukan semua yang lulus pasti penyelam. Bisa saja ada peserta lulus yang tidak pernah jadi penyelam. Arah kalimatnya dibalik.","B":"Opsi ini bertabrakan dengan rantai tadi. Semua penyelam lulus uji, dan tidak ada yang lulus berusia di bawah 18 tahun. Penyelam di bawah 18 tahun tidak mungkin ada.","C":"Premis tidak pernah bilang semua orang dewasa lulus uji, apalagi menjadi penyelam. Di sini dua premis dibalik bersamaan.","E":"P2 hanya bilang peserta di bawah 18 tahun tidak ada yang lulus. Bisa saja mereka ikut uji, lalu gagal. Ikut uji dan lulus uji itu dua hal yang berbeda."}],["Kunci","D, karena penyelam SAR seluruhnya termasuk kelompok yang lulus uji renang, dan kelompok itu tidak berisi orang berusia di bawah 18 tahun."],["Analogi","Semua pemain inti tim sekolahmu sudah lolos tes kesehatan, dan tidak ada yang lolos tes itu sedang cedera. Tanpa memeriksa satu per satu, kamu tahu tidak ada pemain inti yang sedang cedera."],["Jebakan","Opsi E paling licin. Kata lulus diam-diam berubah menjadi mengikuti. Baca kata kerjanya pelan-pelan, karena satu kata bisa memindahkan kesimpulan keluar dari premis."]]},{"k":"E","b":[["Yang ditanya","Pernyataan mana yang membuat kita ragu bahwa kelas daring malam yang menaikkan nilai."],["Kalimat kunci","kelas daring malam itulah yang menaikkan nilai siswa"],["Cara cepat","Melemahkan klaim sebab-akibat berarti menunjukkan penyebab lain yang bisa menghasilkan kenaikan yang sama. Cari opsi yang menawarkan tersangka lain."],["Langkah","Nilai naik dari 68 ke 79 dalam satu semester, dan kepala sekolah menunjuk kelas daring malam. Sekarang tanyakan: adakah hal lain di semester itu yang bisa menaikkan nilai tanpa kelas daring? Opsi E menjawabnya. Soal ujiannya diganti dengan soal yang lebih mudah. Dengan soal yang lebih mudah, nilai bisa naik walaupun tidak ada kelas tambahan apa pun. Kenaikan itu tidak lagi bisa diklaim sebagai hasil kelas daring."],["Kenapa opsi lain gugur",{"A":"Kalau sebagian besar siswa rutin ikut, kelas daring makin masuk akal sebagai penyebab. Opsi ini membela kepala sekolah, padahal kamu diminta melemahkan.","B":"Kenaikan nilai sesudah kelas dibuka sudah ada di soal. Opsi B hanya menceritakan ulang data itu.","C":"Kelas daring bahasa Inggris tidak berkaitan dengan nilai matematika. Informasinya ada, tetapi tidak menyentuh hubungan kelas daring dengan kenaikan nilai.","D":"Keluhan orang tua soal jam pulang memang masalah nyata. Yang dipersoalkan adalah jadwalnya, sementara klaim tentang pengaruh kelas pada nilai tetap utuh."}],["Kunci","E, karena soal ujian yang lebih mudah bisa menaikkan nilai tanpa bantuan kelas daring."],["Analogi","Timbanganmu menunjukkan berat turun 3 kg sejak kamu rutin lari pagi. Ternyata timbangannya baru diganti, dan yang baru selalu menunjukkan angka lebih ringan. Larinya belum tentu berjasa."],["Jebakan","Opsi D terdengar negatif, jadi mudah dikira melemahkan. Melemahkan bukan berarti menjelekkan programnya. Yang harus digoyang adalah hubungan sebabnya: kelas daring menaikkan nilai."]]},{"k":"B","b":[["Yang ditanya","Apa yang pasti terjadi dari tiga premis yang saling menyambung."],["Kalimat kunci","Tenda darurat tidak berdiri sebelum malam."],["Cara cepat","P1 dan P2 membentuk satu rantai: gudang dibuka, terpal bisa diambil, tenda berdiri sebelum malam. P3 bilang ujung rantai itu tidak terjadi. Kalau ujungnya gagal, pangkalnya pun tidak terjadi: gudang tidak dibuka."],["Langkah","Gabungkan P1 dan P2: jika gudang dibuka, tenda berdiri sebelum malam. Sekarang coba andaikan gudang dibuka. Relawan bisa mengambil terpal, lalu tenda berdiri sebelum malam. Hasil itu bertentangan dengan P3, jadi andaian tadi keliru. Gudang pasti tidak dibuka. Polanya bisa kamu pakai lagi: kalau A menjamin B, sedangkan B tidak terjadi, A pun tidak terjadi."],["Kenapa opsi lain gugur",{"A":"Persediaan terpal yang habis tidak pernah disebut di premis. Opsi ini mengarang cerita tambahan supaya semua premis tampak cocok.","C":"Kalau relawan dapat mengambil terpal, P2 memaksa tenda berdiri sebelum malam. Itu bertentangan dengan P3.","D":"Posko lain tidak ada di premis, dan kata mungkin tidak memberi kepastian. Soal meminta yang pasti benar.","E":"Tidak berdiri sebelum malam belum tentu berarti berdiri setelah malam. Bisa saja tenda itu tidak berdiri sama sekali."}],["Kunci","B, karena gudang yang dibuka pasti berujung pada tenda yang berdiri sebelum malam, padahal tenda tidak berdiri."],["Analogi","Setiap kali ibumu pulang, motornya pasti terparkir di garasi. Sore ini garasi kosong. Kamu langsung tahu ibumu belum pulang."],["Jebakan","Opsi E terasa seperti lawan kata yang wajar. Dalam logika, tidak sebelum malam tidak sama dengan setelah malam. Jangan menambah kejadian yang tidak dinyatakan premis."]]},{"k":"E","b":[["Yang ditanya","Pasangan mana yang hubungannya sama dengan higrometer dan kelembapan."],["Kalimat kunci","HIGROMETER : KELEMBAPAN (alat ukur di depan, besaran yang diukur di belakang)"],["Cara cepat","Buat kalimat penghubung: higrometer adalah alat untuk mengukur kelembapan. Masukkan setiap opsi ke kalimat itu. Yang lolos tanpa dipaksa: amperemeter adalah alat untuk mengukur kuat arus."],["Langkah","Uji satu per satu dengan kalimat yang sama. Barometer mengukur tekanan udara, sedangkan cuaca hanya diperkirakan dari tekanan itu. Termometer mengukur suhu, sedangkan demam adalah keadaan tubuh. Suhu : termometer memasang besaran di depan, urutannya terbalik. Mikroskop dipakai untuk melihat benda kecil, bukan mengukur besaran. Amperemeter mengukur kuat arus listrik, persis seperti higrometer mengukur kelembapan."],["Kenapa opsi lain gugur",{"A":"Barometer memang berhubungan dengan cuaca, tetapi yang diukurnya tekanan udara. Cuaca diramal dari hasil ukur itu. Konsepnya mirip, tapi beda.","B":"Termometer mengukur suhu. Demam adalah keadaan orang yang suhunya tinggi, bukan besaran yang angkanya dibaca dari alat.","C":"Isinya benar, tetapi urutannya terbalik: besaran dulu, alat kemudian. Soal memasang alat di depan.","D":"Mikroskop membantu mata melihat sel, tidak memberi angka ukuran. Hubungannya alat bantu lihat, bukan alat ukur."}],["Kunci","E, karena amperemeter adalah alat untuk mengukur kuat arus, sama dengan higrometer yang mengukur kelembapan."],["Analogi","Seperti meteran jahit dan panjang kain. Meteran tidak mengukur baju, melainkan panjangnya."],["Jebakan","Opsi A dan B terasa dekat karena cuaca dan demam akrab dengan alatnya. Periksa apakah kata kedua benar-benar besaran yang angkanya dibaca dari alat itu."]]},{"k":"A","b":[["Yang ditanya","Pernyataan mana yang hubungan ciri tubuh dan tujuannya sama dengan kaktus."],["Kalimat kunci","untuk mengurangi penguapan air"],["Cara cepat","Rumuskan polanya: makhluk hidup memiliki ciri tubuh untuk menghemat air. Cari opsi dengan tujuan yang sama, bukan kata yang sama."],["Langkah","Kaktus hidup di tempat kering. Daunnya berubah menjadi duri supaya air tidak banyak menguap. Intinya: ciri tubuh untuk menghemat air. Unta juga hidup di gurun, dan ginjalnya menghasilkan urin sangat pekat supaya cairan tubuh tidak banyak terbuang. Bagian tubuhnya berbeda, tujuannya sama. Opsi lain punya tujuan lain: melindungi diri, menarik penyerbuk, dan mencari makan."],["Kenapa opsi lain gugur",{"B":"Kata duri memang sama dengan kaktus, tetapi duri landak dipakai untuk melawan pemangsa. Yang dicari tujuannya, bukan kemiripan kata.","C":"Bau busuk bunga bangkai mengundang serangga penyerbuk. Tujuannya berkembang biak, bukan menghemat air.","D":"Tempurung kura-kura adalah pelindung tubuh. Tujuannya keamanan.","E":"Kantong paruh pelikan adalah alat menangkap ikan. Tujuannya mendapatkan makanan."}],["Kunci","A, karena ginjal unta dan duri kaktus sama-sama bekerja menghemat air tubuh."],["Analogi","Dua rumah di daerah kering. Rumah pertama memasang tandon tertutup, rumah kedua memakai keran hemat air. Alatnya beda, maksudnya sama: air jangan cepat habis."],["Jebakan","Mata cepat tertarik ke opsi B karena ada kata duri. Di soal analogi kalimat, kata yang sama sering hanya pengalih. Pegang tujuan di kalimat soal, lalu cocokkan tujuannya."]]},{"k":"C","b":[["Yang ditanya","Taksiran hasil 4.987 × 0,198 + √3.610 yang paling dekat."],["Kalimat kunci","paling mendekati"],["Cara cepat","4.987 × 0,198 kira-kira 5.000 × 0,198 = 990, dikurangi sedikit, jadi sekitar 987. √3.610 sedikit di atas 60, karena 60² = 3.600. Jumlahnya sekitar 1.047. Opsi terdekat 1.045."],["Langkah","Bagian perkalian: 5.000 × 0,198 = 990. Angka 4.987 kurang 13 dari 5.000, jadi hasilnya berkurang 13 × 0,198 ≈ 2,6. Perkaliannya sekitar 987,4. Bagian akar: kelompokkan angka dua-dua dari belakang, 36|10. Akar 36 adalah 6, jadi √3.610 berada di angka 60-an. Tepatnya 60² = 3.600, sehingga √3.610 ≈ 60,1. Jumlah: 987,4 + 60,1 = 1.047,5. Opsi C (1.045) hanya berjarak 2,5."],["Kenapa opsi lain gugur",{"A":"Kalau 0,198 dipotong jadi 0,19 dan akarnya lupa ditambahkan, hasilnya sekitar 947,5. Dua kekeliruan beruntun membawamu ke 950.","B":"Akar 3.610 dikira akar 361, yaitu 19. Pengelompokan angkanya meleset: 3.610 dikelompokkan 36|10, bukan dibaca 361. Hasilnya jadi 987,4 + 19 ≈ 1.006.","D":"Akar 3.610 ditaksir 100 karena angkanya ribuan. Padahal 100² = 10.000, jauh di atas 3.610. Taksiran akar yang terlalu besar membuat hasil sekitar 1.087.","E":"Akar 3.610 tertukar dengan akar 36.100, yaitu 190. Hasilnya 987,4 + 190 ≈ 1.177."}],["Kunci","C, karena 987,4 + 60,1 = 1.047,5, dan 1.045 adalah opsi yang paling dekat."],["Analogi","Seperti menaksir belanja Rp49.870 ditambah Rp6.010. Kamu bulatkan jadi 50 ribu dan 6 ribu, lalu ingat totalnya sedikit di bawah 56 ribu."],["Jebakan","Bagian akar paling sering meleset karena jumlah digitnya. Sebelum menarik akar, kelompokkan angka dua-dua dari belakang, lalu cek dengan mengkuadratkan taksiranmu."]]},{"k":"B","b":[["Yang ditanya","Nilai suku ke-30 dari tabel yang nomor sukunya melompat-lompat."],["Kalimat kunci","Suku ke- 2, 3, 7, 10, 16"],["Cara cepat","Nomor sukunya tidak berurutan, jadi selisih nilai harus dibagi jarak nomor. Dari suku 2 ke 3: (16 − 6) ÷ 1 = 10. Dari suku 3 ke 7: (116 − 16) ÷ 4 = 25. Kenaikan rata-ratanya berubah, tanda pola kuadrat Un = an² + bn + c. Pada pola kuadrat, kenaikan rata-rata dari suku m ke suku n sama dengan a(m + n) + b."],["Langkah","Dua kenaikan rata-rata tadi memberi 5a + b = 10 dan 10a + b = 25. Kurangkan keduanya: 5a = 15, jadi a = 3 dan b = −5. Masukkan ke suku ke-2: 12 − 10 + c = 6, jadi c = 4. Rumusnya Un = 3n² − 5n + 4. Cek di dua titik sisa: U10 = 300 − 50 + 4 = 254 dan U16 = 768 − 80 + 4 = 692. Cocok. Suku ke-30: 3 × 900 − 150 + 4 = 2.554."],["Kenapa opsi lain gugur",{"A":"Kenaikan dari suku 10 ke 16 adalah 73 per suku, lalu dipakai terus sampai suku ke-30. Tabel sudah menunjukkan kenaikannya terus membesar, jadi tidak boleh dianggap tetap.","C":"Ini baru 3n² saja. Bagian −5n + 4 tertinggal, sehingga hasilnya kelebihan 146.","D":"Ini nilai suku ke-31. Rumusnya benar, tetapi nomor sukunya kelebihan satu.","E":"Tanda −5n terbaca +5n, sehingga 150 yang seharusnya dikurangkan malah ditambahkan."}],["Kunci","B, karena rumus 3n² − 5n + 4 cocok di kelima titik tabel dan memberi suku ke-30 = 2.554."],["Analogi","Seperti tagihan listrik yang dicatat bulan ke-2, ke-3, lalu meloncat ke bulan ke-7. Selisih tagihannya baru bermakna setelah dibagi banyak bulan yang terlewat."],["Jebakan","Nomor suku yang melompat adalah inti soal ini. Kalau selisih nilai dihitung langsung tanpa dibagi jarak nomornya, polanya tidak akan pernah terlihat."]]},{"k":"E","b":[["Yang ditanya","Pasangan X dan Y di kolom kelima."],["Kalimat kunci","tabel dua baris yang setiap kolomnya lahir dari kolom sebelumnya"],["Cara cepat","Lihat kolom pertama (7 dan 3) dan kolom kedua (10 dan 4). Ternyata 7 + 3 = 10 dan 7 − 3 = 4. Aturannya: atas baru = atas + bawah, bawah baru = atas − bawah. Dari kolom keempat (20 dan 8): X = 28 dan Y = 12."],["Langkah","Uji aturan di semua kolom. Kolom 2 ke kolom 3: 10 + 4 = 14 dan 10 − 4 = 6. Kolom 3 ke kolom 4: 14 + 6 = 20 dan 14 − 6 = 8. Cocok terus. Kolom 4 ke kolom 5: X = 20 + 8 = 28 dan Y = 20 − 8 = 12. Kedua angka kolom kelima dihitung dari kolom keempat yang sama."],["Kenapa opsi lain gugur",{"A":"X = 20 berasal dari kolom ketiga (14 + 6). Hitungannya berangkat dari kolom yang salah, sehingga X sama dengan angka yang sudah ada di kolom keempat.","B":"X sudah benar, tetapi Y dihitung 28 − 8, memakai X yang baru. Kedua angka kolom kelima harus dihitung dari kolom keempat: 20 − 8.","C":"Ini isi kolom keenam: 28 + 12 dan 28 − 12. Kamu melangkah satu kolom terlalu jauh.","D":"Isinya sama dengan kolom keempat. Kolom keempat dihitung ulang dari kolom ketiga, belum dilanjutkan ke kolom kelima."}],["Kunci","E, karena dari kolom keempat (20 dan 8) diperoleh 20 + 8 = 28 dan 20 − 8 = 12."],["Analogi","Seperti buku kas dua kolom yang diperbarui setiap minggu. Catatan minggu depan selalu dihitung dari catatan minggu ini secara utuh. Kalau separuhnya diambil dari angka yang sudah diperbarui, kasnya kacau."],["Jebakan","Baris atas 7, 10, 14, 20 menggoda dibaca sebagai deret sendiri dengan selisih 3, 4, 6. Coba lihat: selisih itu justru angka-angka di baris bawah. Kalau dua baris tampak saling memberi angka, periksa hubungan antarbaris lebih dulu."]]},{"k":"C","b":[["Yang ditanya","Nilai X di baris ketiga."],["Kalimat kunci","bilangan negatif di kolom pertama"],["Cara cepat","Baris pertama: 3² = 9, lalu 9 − 2 = 7. Aturannya: angka pertama dipangkatkan angka kedua, lalu dikurangi angka kedua. Baris ketiga: (−4)² − 2 = 16 − 2 = 14."],["Langkah","Cek aturan di baris kedua dulu, karena baris ini memuat bilangan negatif: (−3)³ = −27, lalu −27 − 3 = −30. Cocok. Baru hitung baris ketiga. (−4)² = 16, karena bilangan negatif yang dipangkatkan genap hasilnya positif. Setelah itu 16 − 2 = 14."],["Kenapa opsi lain gugur",{"A":"Tanda negatif tidak ikut dipangkatkan, sehingga (−4)² dibaca −16. Padahal −4 × −4 hasilnya positif 16.","B":"Pangkat diperlakukan seperti perkalian: −4 × 2 = −8, lalu −8 − 2 = −10. Aturan ini sudah gagal di baris pertama, karena 3 × 2 − 2 = 4, bukan 7.","D":"Langkah pangkatnya sudah benar, tetapi pengurangan dengan angka kedua terlupa.","E":"Angka kedua ditambahkan, bukan dikurangkan. Coba di baris pertama: 9 + 2 = 11, bukan 7."}],["Kunci","C, karena (−4)² − 2 = 16 − 2 = 14, dengan aturan yang sama yang menghasilkan 7 dan −30."],["Analogi","Dua tanda minus yang dikalikan saling meniadakan, seperti berbalik arah dua kali yang membuatmu menghadap ke depan lagi."],["Jebakan","Bilangan negatif di kolom pertama sengaja dipasang. Ingat: negatif dipangkat ganjil tetap negatif (−27), dipangkat genap menjadi positif (16)."]]},{"k":"A","b":[["Yang ditanya","Pasangan pembagian yang kedua ruasnya bernilai sama."],["Kalimat kunci","bernilai sama"],["Cara cepat","Hilangkan koma dengan menggeser koma pada bilangan yang dibagi dan pembaginya sama banyak. 7,2 ÷ 0,6 = 72 ÷ 6 = 12, dan 84 ÷ 7 = 12. Sama."],["Langkah","Ruas kiri A sampai D semuanya bernilai 12, sedangkan ruas kiri E bernilai 9. Penentunya ada di ruas kanan. A: 84 ÷ 7 = 12. B: 66 ÷ 6 = 11. C: 1,3 ÷ 0,1 = 13 ÷ 1 = 13. D: 1,2 ÷ 0,01 = 120 ÷ 1 = 120. E: 6,3 ÷ 0,7 = 9, sedangkan 0,9 ÷ 0,01 = 90. Hanya pasangan A yang kedua ruasnya 12."],["Kenapa opsi lain gugur",{"B":"Ruas kiri 4,8 ÷ 0,4 memang 12, tetapi ruas kanan 66 ÷ 6 = 11. Kalau berhenti di ruas kiri, kamu akan tertipu.","C":"Ruas kiri 12, ruas kanan 1,3 ÷ 0,1 = 13. Selisih satu ini mudah lolos kalau ruas kanan tidak dihitung.","D":"1,2 ÷ 0,01 sama dengan 120, bukan 12. Pembaginya punya dua angka di belakang koma, jadi koma digeser dua langkah.","E":"Ruas kiri 9, ruas kanan 90. Pola angkanya mirip, tetapi pembagi 0,01 membuat ruas kanan sepuluh kali lebih besar."}],["Kunci","A, karena 7,2 ÷ 0,6 dan 84 ÷ 7 sama-sama bernilai 12."],["Analogi","Uang Rp7.200 untuk membeli barang seharga Rp600 sama saja dengan 72 lembar seratusan untuk barang seharga 6 lembar seratusan. Keduanya dapat 12 barang."],["Jebakan","Empat ruas kiri bernilai 12, jadi ruas kiri tampak meyakinkan di mana-mana. Biasakan menghitung kedua ruas sebelum memilih."]]},{"k":"E","b":[["Yang ditanya","Pasangan perkalian yang hasilnya sama."],["Kalimat kunci","bernilai sama"],["Cara cepat","Bandingkan faktornya sebelum mengalikan. 45 = 9 × 5 dan 64 = 16 × 4, sedangkan 36 = 9 × 4 dan 80 = 16 × 5. Isi faktornya persis sama, hanya bertukar tempat. Hasil keduanya 2.880."],["Langkah","Cek opsi lain dengan hitungan. B: 48 × 60 = 2.880, tetapi 32 × 85 = 2.720. C: 72 × 40 = 2.880, tetapi 54 × 52 = 2.808. A: 28 × 330 = 9.240, sedangkan 38 × 230 = 8.740. D: 26 × 450 = 11.700, sedangkan 45 × 270 = 12.150. E: 45 × 64 = 2.880 dan 36 × 80 = 2.880."],["Kenapa opsi lain gugur",{"A":"Pasangan 28 dan 38, 330 dan 230 tampak seperti tukar angka. Ternyata hasilnya 9.240 dan 8.740. Mirip bentuk belum tentu sama nilai.","B":"Ruas kiri 2.880 sama dengan kunci, tetapi 32 × 85 = 2.720. Hanya satu ruas yang diperiksa.","C":"Ruas kiri lagi-lagi 2.880, ruas kanan 54 × 52 = 2.808. Selisihnya kecil, jadi harus dihitung, tidak cukup dikira-kira.","D":"Kalau angkanya 27, pasangan ini memang sama (27 × 450 = 12.150). Karena tertulis 26, hasilnya 11.700."}],["Kunci","E, karena 45 × 64 dan 36 × 80 tersusun dari faktor yang sama, yaitu 9, 16, 4, dan 5, sehingga keduanya bernilai 2.880."],["Analogi","Sekotak kue berisi 4 baris × 9 kue sama banyaknya dengan 9 baris × 4 kue. Susunannya berubah, jumlah kuenya tidak."],["Jebakan","Tiga ruas kiri sama-sama 2.880, dan dua opsi tampak seperti cermin angka. Pecah angka menjadi faktor, lalu cocokkan isinya."]]},{"k":"C","b":[["Yang ditanya","Pasangan yang kedua ruasnya TIDAK sama."],["Kalimat kunci","TIDAK bernilai sama"],["Cara cepat","Hitung setiap ruas, lalu cari yang beda. C: (84 ÷ 7) + (5 × 3) = 12 + 15 = 27, sedangkan (125 ÷ 5) + 4 = 25 + 4 = 29. Beda."],["Langkah","A: 9 × 7 = 63 dan 72 − 9 = 63. B: 9 + 30 = 39 dan 13 × 3 = 39. D: 90 − 12 = 78 dan 26 × 3 = 78. E: 12 × 7 = 84 dan 98 − 14 = 84. Empat pasangan bernilai sama. Pasangan C berbeda, 27 dan 29."],["Kenapa opsi lain gugur",{"A":"Kedua ruas bernilai 63. Pasangan ini sama, jadi bukan yang dicari.","B":"Ruas kiri 9 + 30 = 39, ruas kanan 13 × 3 = 39. Sama.","D":"90 − 12 = 78 dan 26 × 3 = 78. Sama juga.","E":"12 × 7 = 84 dan 98 − 14 = 84. Kalau kamu memilih ini, cek lagi apakah isi kurung (3 + 4) sudah dihitung lebih dulu."}],["Kunci","C, karena ruas kirinya 27 sedangkan ruas kanannya 29."],["Analogi","Seperti mencari kaus kaki yang tidak punya pasangan di keranjang cucian. Cocokkan dulu yang berpasangan, sisanya ketahuan sendiri."],["Jebakan","Kata TIDAK membalik arah pencarian. Banyak yang menghitung dengan benar, lalu memilih pasangan pertama yang sama karena kebiasaan. Garis bawahi kata TIDAK sebelum mulai."]]},{"k":"B","b":[["Yang ditanya","Kapasitas penuh tangki."],["Kalimat kunci","terisi 10% … ditambah 3.000 liter … terisi 60%"],["Cara cepat","Tambahan 3.000 liter mengisi selisih persennya: 60% − 10% = 50%. Kalau 50% = 3.000 liter, 100% = 6.000 liter."],["Langkah","Pisahkan mana yang persen dan mana yang liter. Isi tangki berubah dari 10% ke 60%, naik 50% dari kapasitas. Kenaikan itu terjadi karena tambahan 3.000 liter. Jadi 50% kapasitas = 3.000 liter, dan kapasitas penuh = 2 × 3.000 = 6.000 liter. Cek balik: 10% dari 6.000 = 600 liter, ditambah 3.000 menjadi 3.600 liter, dan 3.600 memang 60% dari 6.000."],["Kenapa opsi lain gugur",{"A":"3.000 dibagi 60%, seolah 3.000 liter adalah isi akhir. Padahal 3.000 liter hanya tambahannya.","C":"Kapasitas 6.000 sudah ketemu, lalu isi awal 600 liter ikut ditambahkan. Kapasitas tangki tidak berubah karena isinya.","D":"Isi awal (600), isi akhir (3.600), dan tambahan (3.000) dijumlahkan semua. Angka-angka itu menggambarkan air yang sama pada waktu berbeda, jadi tidak boleh dijumlah.","E":"3.000 dibagi 10%. Tambahan air disamakan dengan isi awal, padahal ia setara dengan selisih 50%."}],["Kunci","B, karena 3.000 liter setara dengan 50% kapasitas, sehingga kapasitas penuhnya 6.000 liter."],["Analogi","Baterai ponselmu naik dari 10% ke 60% setelah diisi 2.000 mAh. Berarti 50% baterai = 2.000 mAh, dan baterai penuh 4.000 mAh."],["Jebakan","Angka 3.000 liter harus dipasangkan dengan selisih persen, bukan dengan persen awal atau persen akhir. Begitu salah pasang, semua opsi lain terasa masuk akal."]]},{"k":"D","b":[["Yang ditanya","Berapa lama kolam penuh, dihitung sejak keran P dan Q dibuka."],["Kalimat kunci","Satu jam kemudian keran R juga dibuka"],["Cara cepat","Pakai bagian kolam per jam: P = 1/4, Q = 1/12, R = −1/6. Jam pertama (P dan Q) mengisi 1/3 kolam. Sesudah itu ketiganya mengisi 1/6 kolam per jam. Sisa 2/3 kolam butuh 4 jam. Total 1 + 4 = 5 jam."],["Langkah","Samakan penyebut menjadi 12. Setiap jam P mengisi 3/12 kolam, Q mengisi 1/12, dan R membuang 2/12. Satu jam pertama hanya P dan Q yang terbuka: 4/12 = 1/3 kolam. Sisa kolam 2/3. Mulai jam kedua ketiganya terbuka: 3/12 + 1/12 − 2/12 = 2/12 = 1/6 kolam per jam. Waktu untuk sisanya: 2/3 ÷ 1/6 = 4 jam. Pertanyaan dihitung sejak P dan Q dibuka, jadi satu jam pertama ikut dijumlahkan: 5 jam."],["Kenapa opsi lain gugur",{"A":"R dihitung ikut mengisi, sehingga lajunya menjadi 1/2 kolam per jam. R adalah keran pembuang, jadi lajunya dikurangkan.","B":"R tidak dihitung sama sekali. P dan Q berdua memang memenuhi kolam dalam 3 jam, tetapi soal menyebut R ikut terbuka.","C":"Angka 4 jam ini baru waktu sesudah R dibuka. Satu jam pertama belum ditambahkan.","E":"Ketiga keran dianggap dibuka bersamaan sejak awal, sehingga 1/6 kolam per jam selama 6 jam. Jeda satu jam di soal terlewat."}],["Kunci","D, karena satu jam pertama mengisi 1/3 kolam, lalu sisa 2/3 kolam terisi dalam 4 jam, sehingga totalnya 5 jam."],["Analogi","Kamu mengisi ember dengan dua keran, lalu adikmu membuka sumbat di dasarnya. Air tetap naik walau lebih pelan, dan waktu sebelum sumbat dibuka tetap ikut dihitung."],["Jebakan","Soal ini punya dua titik waktu: saat P dan Q dibuka, dan saat R dibuka. Pertanyaannya dihitung dari titik pertama. Opsi C menunggu orang yang lupa menambahkan jam pertama."]]},{"k":"A","b":[["Yang ditanya","Apakah harga 5 map dan 5 spidol bisa ditentukan dengan pasti."],["Kalimat kunci","5 map dan 5 spidol"],["Cara cepat","Yang ditanya jumlah keduanya, bukan harga masing-masing. 5 map dan 5 spidol adalah 2,5 kali 2 map dan 2 spidol. Pernyataan (1) memberi Rp18.000, jadi jawabannya 2,5 × 18.000 = Rp45.000."],["Langkah","Pernyataan (1): 2 map dan 2 spidol Rp18.000, berarti 1 map dan 1 spidol Rp9.000, dan 5 map dan 5 spidol Rp45.000. Cukup, walaupun harga satu map belum diketahui. Pernyataan (2): map lebih mahal Rp3.000. Harga sepasang bisa Rp5.000 + Rp2.000 atau Rp10.000 + Rp7.000, jadi totalnya berubah-ubah. Tidak cukup. Pernyataan (1) saja cukup, pernyataan (2) saja tidak."],["Kenapa opsi lain gugur",{"B":"Pernyataan (2) hanya memberi selisih harga. Selisih Rp3.000 bisa dimiliki pasangan harga murah maupun mahal, jadi totalnya tidak tertentu.","C":"Menggabungkan (1) dan (2) memang memberi harga masing-masing barang, yaitu Rp6.000 dan Rp3.000. Soal tidak memintanya. Jumlah sepasang dari (1) sudah cukup.","D":"Pernyataan (2) dianggap cukup sendiri, padahal selisih saja tidak menentukan jumlah.","E":"Kesannya data kurang karena harga satuan tidak diketahui. Soal menanyakan jumlah, dan jumlah itu bisa dihitung dari kelipatan pernyataan (1)."}],["Kunci","A, karena 5 map dan 5 spidol tepat 2,5 kali isi pernyataan (1), sedangkan pernyataan (2) tidak menentukan total."],["Analogi","Dua porsi bakso dan dua es teh Rp40.000. Kamu tahu lima porsi bakso dan lima es teh Rp100.000 tanpa perlu tahu harga baksonya sendiri."],["Jebakan","Refleks banyak orang: harus tahu harga map dan harga spidol dulu. Baca lagi yang ditanya. Kalau yang ditanya kelipatan dari data, satu pernyataan sudah cukup."]]},{"k":"E","b":[["Yang ditanya","Apakah total berat karung pasti tidak melebihi 5.000 kg."],["Kalimat kunci","Karung terberat beratnya 48 kg dan karung teringan beratnya 40 kg"],["Cara cepat","Gabungkan (1) dan (2). Kalau sisa karung seringan mungkin, total sekitar 4.400 kg. Kalau seberat mungkin, total sekitar 5.270 kg. Rentangnya melewati 5.000 kg, jadi jawabannya bisa ya, bisa tidak."],["Langkah","Pernyataan (1) saja: 110 karung, tetapi beratnya tidak diketahui. Tidak cukup. Pernyataan (2) saja: tahu berat terberat dan teringan, tetapi tidak tahu banyaknya karung. Tidak cukup. Gabungan: ada satu karung 48 kg dan satu karung 40 kg, sedangkan 108 karung sisanya beratnya di antara 40 dan 48 kg. Kalau sisanya 40 kg semua, total 4.408 kg, aman. Kalau sisanya 48 kg semua, total 5.272 kg, melebihi batas. Dua keadaan yang sama-sama mungkin memberi jawaban berbeda. Bersama-sama pun tidak cukup."],["Kenapa opsi lain gugur",{"A":"Tahu jumlah karung belum berarti tahu beratnya. 110 karung kapas dan 110 karung semen tentu berbeda bebannya.","B":"Berat terberat dan teringan tanpa jumlah karung tidak bisa dijadikan total.","C":"Gabungan baru memberi rentang 4.408 sampai 5.272 kg. Pilihan ini muncul kalau semua karung dianggap seberat 40 kg atau seberat 48 kg, padahal soal tidak mengatakannya.","D":"Tidak satu pun pernyataan cukup sendirian, jadi pilihan ini gugur sejak awal."}],["Kunci","E, karena dengan kedua pernyataan pun total berat bisa di bawah atau di atas 5.000 kg."],["Analogi","Kamu tahu ada 20 tamu, dan setiap tamu makan paling sedikit 1 piring dan paling banyak 3 piring. Kamu belum bisa memastikan 40 piring cukup."],["Jebakan","Pernyataan (2) terasa lengkap karena memuat dua angka berat. Terberat dan teringan hanyalah batas. Karung di antaranya bisa berapa saja."]]},{"k":"A","b":[["Yang ditanya","Apakah pesanan pasti selesai paling lama 4 hari jika dikerjakan 6 penjahit."],["Kalimat kunci","menugaskan 6 penjahit"],["Cara cepat","Pernyataan (1): 10 penjahit × 3 hari = 30 hari kerja. Dibagi 6 penjahit = 5 hari. Lebih dari 4 hari, jadi jawabannya pasti tidak. Jawaban tidak yang pasti tetap berarti cukup."],["Langkah","Pekerjaannya sama, penjahitnya lebih sedikit, waktunya lebih lama. 10 penjahit butuh 3 hari, berarti pekerjaannya setara 30 hari kerja satu penjahit. 6 penjahit butuh 30 ÷ 6 = 5 hari. Pertanyaan terjawab pasti, jadi (1) cukup. Pernyataan (2): 12 seragam per hari per penjahit, tetapi banyak seragam yang dipesan tidak disebut. Kalau pesanannya 200 seragam, 6 penjahit selesai dalam 3 hari. Kalau 600 seragam, lebih dari 8 hari. Tidak cukup."],["Kenapa opsi lain gugur",{"B":"Kecepatan 12 seragam per hari baru berguna kalau banyak seragam diketahui. Soal tidak menyebutnya.","C":"Pernyataan (1) sudah memberi jawaban pasti tanpa bantuan (2). Kecepatan per penjahit tidak perlu, karena pekerjaan sudah terukur dalam hari kerja penjahit.","D":"Pernyataan (2) dianggap cukup sendiri, padahal banyak seragam tidak diketahui.","E":"Kalau kamu sempat mengira 6 penjahit lebih cepat daripada 10 penjahit, hasilnya terasa janggal dan kamu jadi ragu. Penjahit lebih sedikit berarti waktu lebih lama, dan hasil 5 hari itu pasti."}],["Kunci","A, karena pernyataan (1) memastikan pesanan selesai dalam 5 hari, sehingga jawaban tidak sudah pasti, sedangkan pernyataan (2) tidak memuat banyak seragam."],["Analogi","Pagar yang dicat 4 orang selesai dalam 6 jam. Kalau yang datang hanya 3 orang, kamu tahu pasti pengecatan butuh 8 jam."],["Jebakan","Jawaban tidak sering dikira berarti pernyataannya tidak cukup. Dalam soal seperti ini, yang dinilai adalah kepastian jawabannya, ya atau tidak."]]},{"k":"D","b":[["Yang ditanya","Apakah banyak peserta putri bisa ditentukan."],["Kalimat kunci","diikuti 84 peserta"],["Cara cepat","Total 84 sudah tertulis di soal. Pernyataan (1): 3/7 × 84 = 36 putri. Pernyataan (2): (84 − 12) ÷ 2 = 36 putri. Masing-masing cukup sendiri."],["Langkah","Data di kalimat soal boleh dipakai bersama setiap pernyataan. Pernyataan (1): perbandingan 4 : 3 berarti 7 bagian = 84 orang, satu bagian 12 orang, putri 3 bagian = 36 orang. Pernyataan (2): putra = putri + 12, sehingga putri + putri + 12 = 84, dan putri = 36. Keduanya sampai ke 36 tanpa saling membantu."],["Kenapa opsi lain gugur",{"A":"Setelah (1) terbukti cukup, pemeriksaan berhenti. Pernyataan (2) belum diuji, padahal ia juga cukup sendiri.","B":"Kebalikannya: (2) diuji dan cukup, tetapi (1) tidak dicek.","C":"Tidak perlu digabung. Total 84 di soal sudah membuat setiap pernyataan lengkap.","E":"Kesan data kurang muncul kalau angka 84 di soal terlupa. Tanpa total memang tidak cukup, tetapi totalnya ada."}],["Kunci","D, karena dengan total 84 dari soal, pernyataan (1) saja dan pernyataan (2) saja masing-masing menghasilkan 36 putri."],["Analogi","Uang 84 ribu dibagi kakak dan adik. Bagian adik bisa diketahui dari petunjuk perbandingannya 4 : 3, bisa juga dari petunjuk kakak dapat 12 ribu lebih banyak."],["Jebakan","Banyak yang menilai pernyataan seolah kalimat soal tidak ada, lalu mengira semuanya kurang. Angka di kalimat soal ikut dipakai."]]},{"k":"B","b":[["Yang ditanya","Apakah harga satu kilogram cabai pada awal bulan bisa dihitung."],["Kalimat kunci","Rp55.000 per kilogram, yaitu 25% lebih tinggi daripada harga awal bulan"],["Cara cepat","Pernyataan (2): Rp55.000 adalah 125% harga awal, jadi harga awal = 55.000 ÷ 1,25 = Rp44.000. Pernyataan (1) hanya memuat persen tanpa rupiah."],["Langkah","Pernyataan (1): harga naik 15% di pertengahan bulan, tetapi tidak ada satu pun harga dalam rupiah. Harga awal bisa berapa saja. Tidak cukup. Pernyataan (2): harga akhir bulan Rp55.000, dan itu 25% di atas harga awal. Artinya Rp55.000 = 125% harga awal. Satu persen = 55.000 ÷ 125 = 440, dan harga awal = 100 × 440 = Rp44.000. Cukup."],["Kenapa opsi lain gugur",{"A":"Persen kenaikan tanpa satu harga rupiah tidak bisa dijadikan angka. Harga awal Rp30.000 maupun Rp60.000 sama-sama bisa naik 15%.","C":"Harga pertengahan bulan tidak dibutuhkan. Pernyataan (2) sudah langsung mengaitkan harga akhir dengan harga awal.","D":"Pernyataan (1) dianggap cukup, padahal tidak memuat harga rupiah sama sekali.","E":"Kesannya harga awal belum diketahui, sehingga persen dari harga awal tidak bisa dipakai. Justru dengan hitung balik, 55.000 ÷ 1,25 langsung memberi harga awal."}],["Kunci","B, karena Rp55.000 adalah 125% harga awal, sehingga harga awal pasti Rp44.000, sedangkan pernyataan (1) tidak memuat rupiah."],["Analogi","Gajimu sekarang Rp5.000.000, dan itu sudah naik 25% dari gaji pertama. Gaji pertamamu pasti Rp4.000.000."],["Jebakan","Kekeliruan hitung yang sering muncul: mengurangi 25% dari Rp55.000 dan mendapat Rp41.250. Persen 25 itu dihitung dari harga awal, jadi harga awal dicari dengan membagi 1,25."]]},{"k":"C","b":[["Yang ditanya","Apakah n pasti habis dibagi 12."],["Kalimat kunci","habis dibagi 12"],["Cara cepat","Pernyataan (1): n = 8 tidak habis dibagi 12, n = 12 habis. Tidak cukup. Pernyataan (2): n = 18 tidak, n = 12 ya. Tidak cukup. Gabungan: habis dibagi 4 dan 6 berarti habis dibagi KPK(4, 6) = 12. Jawabannya pasti ya."],["Langkah","Untuk pertanyaan apakah, cari dua contoh yang memberi jawaban berbeda. Kalau ketemu, pernyataan itu tidak cukup. Bilangan 8 dan 12 sama-sama habis dibagi 4, tetapi hanya 12 yang habis dibagi 12. Bilangan 18 dan 12 sama-sama habis dibagi 6, tetapi hanya 12 yang habis dibagi 12. Kalau kedua pernyataan berlaku bersamaan, n habis dibagi KPK dari 4 dan 6. Faktorkan: 4 = 2², 6 = 2 × 3, KPK = 2² × 3 = 12."],["Kenapa opsi lain gugur",{"A":"12 memang kelipatan 4, tetapi tidak semua kelipatan 4 adalah kelipatan 12. Contohnya 8.","B":"Sama halnya dengan 6: angka 18 habis dibagi 6, tetapi tidak habis dibagi 12.","D":"Masing-masing pernyataan sudah gugur dengan satu contoh, 8 untuk (1) dan 18 untuk (2).","E":"Kalau syaratnya dikira habis dibagi 4 × 6 = 24, gabungan terlihat kurang. Yang berlaku adalah KPK, yaitu 12. Nilai n juga tidak perlu diketahui, karena jawaban ya sudah pasti."}],["Kunci","C, karena bilangan yang habis dibagi 4 dan habis dibagi 6 pasti habis dibagi KPK-nya, yaitu 12."],["Analogi","Bus A lewat setiap 4 menit, bus B setiap 6 menit. Keduanya lewat bersamaan setiap 12 menit, bukan setiap 24 menit."],["Jebakan","Hasil kali 4 × 6 = 24 menggoda karena terasa seperti gabungan. Untuk dua syarat habis dibagi yang berlaku bersamaan, pakai KPK."]]},{"k":"E","b":[["Yang ditanya","Apakah banyak siswa yang mengikuti kedua kegiatan bisa ditentukan."],["Kalimat kunci","atau tidak mengikuti keduanya"],["Cara cepat","Gabungan memberi 18 + 15 = 33 keikutsertaan di kelas 30 siswa. Kalau setiap siswa ikut kegiatan, irisannya 3. Soal mengizinkan siswa tidak ikut apa pun, jadi irisannya bisa 3, 4, 5, dan seterusnya. Tidak cukup."],["Langkah","Pernyataan (1) saja: tanpa banyak siswa di kelas, irisan tidak bisa dicari. Pernyataan (2) saja: hanya total kelas. Gabungan: siswa yang ikut minimal satu kegiatan = 33 − irisan. Angka itu tidak boleh lebih dari 30, sehingga irisan paling sedikit 3. Contoh pertama: irisan 3, dan semua 30 siswa ikut kegiatan. Contoh kedua: irisan 5, ada 28 siswa yang ikut kegiatan dan 2 siswa tidak ikut apa-apa. Keduanya sesuai soal, tetapi jawabannya berbeda."],["Kenapa opsi lain gugur",{"A":"Tanpa banyak siswa di kelas, angka 18 dan 15 tidak bisa dipakai menghitung irisan.","B":"Total 30 siswa saja tidak berkata apa pun tentang paduan suara atau basket.","C":"Hasil 18 + 15 − 30 = 3 hanya benar kalau setiap siswa ikut minimal satu kegiatan. Soal justru menyebut siswa boleh tidak mengikuti keduanya.","D":"Tidak satu pun pernyataan cukup sendirian, jadi pilihan ini gugur sejak awal."}],["Kunci","E, karena siswa yang tidak ikut kegiatan apa pun membuat irisannya bisa 3, 5, atau angka lain."],["Analogi","Di arisan 30 orang, 18 orang membawa kue dan 15 orang membawa minuman. Kalau ada yang datang dengan tangan kosong, kamu belum bisa memastikan berapa orang yang membawa keduanya."],["Jebakan","Rumus 18 + 15 − 30 sangat akrab, jadi tangan langsung menulis 3. Sebelum memakai rumus itu, cek kalimat soal: adakah siswa yang tidak ikut apa pun?"]]},{"k":"D","b":[["Yang ditanya","Pernyataan yang benar di semua susunan jadwal yang mungkin."],["Kalimat kunci","pasti benar"],["Cara cepat","Anggrek tidak membawakan gempa, jadi Anggrek tidak tampil Rabu. Uji tiga tempat yang tersisa untuk pasangan Anggrek lalu Cempaka. Hanya Anggrek Selasa dan Cempaka Rabu yang lolos. Cempaka tampil Rabu, jadi pasti membawakan gempa."],["Langkah","Gempa ada di hari Rabu. Pasangan banjir lalu kebakaran harus berurutan dan tidak boleh memakai Rabu, jadi pasangan itu jatuh di Senin–Selasa atau Kamis–Jumat. Pasangan Anggrek lalu Cempaka tinggal tiga kemungkinan. Pertama, Anggrek Senin dan Cempaka Selasa. Anggrek tidak boleh banjir, jadi banjir–kebakaran pindah ke Kamis–Jumat. Topik Senin dan Selasa tinggal longsor dan puting beliung, padahal longsor milik Kenanga. Gagal. Kedua, Anggrek Kamis dan Cempaka Jumat. Dengan alasan yang sama, banjir–kebakaran di Senin–Selasa, dan longsor lagi-lagi jatuh ke Anggrek atau Cempaka. Gagal. Ketiga, Anggrek Selasa dan Cempaka Rabu. Lolos, dan dari sini muncul tiga susunan yang sah. Di ketiganya Cempaka tampil Rabu dan membawakan gempa."],["Kenapa opsi lain gugur",{"A":"Bakung tampil Kamis hanya di salah satu susunan. Di dua susunan lain Bakung tampil Jumat.","B":"Dahlia membawakan banjir di dua susunan, tetapi di susunan lain Dahlia membawakan kebakaran. Benar di sebagian susunan belum berarti pasti.","C":"Kenanga tampil Senin di dua susunan, tetapi bisa juga tampil Kamis.","E":"Anggrek membawakan kebakaran hanya di satu susunan. Di dua susunan lain topiknya puting beliung."}],["Kunci","D, karena Anggrek hanya bisa tampil Selasa, sehingga Cempaka selalu tampil Rabu, hari topik gempa."],["Analogi","Seperti menyusun jadwal piket kelas. Kadang ada beberapa jadwal yang sah, dan yang pasti hanyalah hal yang sama di semua jadwal itu."],["Jebakan","Begitu menemukan satu susunan yang cocok, banyak orang langsung memilih opsi yang benar di susunan itu. Soal pasti benar menuntut kamu memeriksa semua susunan, atau menemukan hal yang tidak bisa berubah."]]},{"k":"B","b":[["Yang ditanya","Siapa yang duduk tepat di hadapan Hasan."],["Kalimat kunci","Semua petugas duduk menghadap ke tengah meja."],["Cara cepat","Tempatkan Fajar, Gita, Indah, dan Joko. Dua kursi yang tersisa ternyata saling berhadapan, dan hanya Hasan dan Lina yang belum duduk. Hasan pasti berhadapan dengan Lina, di kursi mana pun ia duduk."],["Langkah","Gambar enam kursi, beri nomor 1 sampai 6 searah jarum jam dilihat dari atas, lalu dudukkan Fajar di kursi 1. Bagi orang yang menghadap ke tengah, sebelah kanannya berada di arah berlawanan jarum jam. Gita di kanan Fajar, jadi Gita di kursi 6. Hadapan kursi 6 adalah kursi 3, jadi Indah di kursi 3. Kiri Indah searah jarum jam, jadi Joko di kursi 4. Kursi kosong tinggal 2 dan 5, dan keduanya berhadapan. Hasan dan Lina mengisi dua kursi itu dengan urutan apa pun."],["Kenapa opsi lain gugur",{"A":"Fajar berada dua kursi dari Hasan bila Hasan duduk di kursi 5. Pada meja enam kursi, orang di hadapanmu berjarak tiga kursi.","C":"Gita duduk bersebelahan dengan salah satu kursi kosong, bukan di hadapannya.","D":"Indah juga hanya berjarak dua kursi dari kursi 5. Hadapan selalu berjarak tiga kursi.","E":"Joko muncul kalau kiri Indah dibaca sebagai kanan. Joko lalu pindah ke kursi 2, dan susunan kursi kosongnya ikut berubah. Kiri dan kanan di meja bundar dilihat dari orang yang duduk menghadap ke tengah."}],["Kunci","B, karena setelah empat petugas ditempatkan, dua kursi sisa saling berhadapan dan hanya bisa diisi Hasan dan Lina."],["Analogi","Seperti duduk di meja makan bundar keluarga. Kananmu adalah tangan kananmu sendiri saat menghadap ke meja, bukan kanan orang yang melihat dari pintu."],["Jebakan","Kiri dan kanan paling sering terbalik di soal meja bundar. Bayangkan dirimu duduk di kursi tokoh itu, menghadap ke tengah, lalu angkat tangan kananmu."]]},{"k":"D","b":[["Yang ditanya","Pernyataan yang benar di semua urutan kedatangan yang mungkin."],["Kalimat kunci","Kapal T bukan kapal yang tiba paling akhir."],["Cara cepat","Kapal yang tiba paling akhir tidak boleh punya kapal lain yang wajib tiba sesudahnya. P, Q, R, dan S masing-masing punya kapal yang wajib tiba sesudahnya. Calonnya tinggal T dan U. T dilarang tiba paling akhir, jadi U pasti paling akhir."],["Langkah","Susun dua rantai: P, R, S, T dan P, Q, U. Kapal P berada di pangkal kedua rantai, jadi P tiba pertama. Urutan yang mungkin ada empat: P Q R S T U, P R Q S T U, P R S Q T U, dan P R S T Q U. Di keempatnya U berada di urutan keenam."],["Kenapa opsi lain gugur",{"A":"Q tiba kedua hanya pada urutan P Q R S T U. Di urutan lain Q bisa ketiga, keempat, atau kelima.","B":"R tiba sebelum Q pada tiga urutan, tetapi pada P Q R S T U justru Q yang lebih dulu.","C":"T tiba kelima pada tiga urutan, tetapi pada P R S T Q U kapal T tiba keempat.","E":"S tiba ketiga pada dua urutan, sedangkan pada dua urutan lain S tiba keempat."}],["Kunci","D, karena setiap kapal selain T dan U punya kapal yang wajib tiba sesudahnya, dan T dilarang tiba paling akhir."],["Analogi","Antrean di loket: orang terakhir adalah orang yang tidak punya siapa pun di belakangnya. Kalau hampir semua orang sudah pasti punya orang di belakangnya, calon orang terakhir tinggal sedikit."],["Jebakan","Ketentuan 1 sampai 3 hanya memberi urutan sebagian. Jangan langsung menulis satu urutan lalu memilih opsi yang cocok dengannya. Ketentuan 4 yang pendek itulah penentunya."]]},{"k":"C","b":[["Yang ditanya","Biaya termurah untuk mendapatkan paling sedikit 130 nasi kotak."],["Kalimat kunci","paling sedikit 130 nasi kotak"],["Cara cepat","Harga per kotak: Melati Rp19.000, Mawar Rp17.000, Teratai Rp16.000. Utamakan Teratai, lalu cari tambahan yang paling hemat. 2 Teratai (100 kotak) dan 1 Mawar (35 kotak) memberi 135 kotak dengan biaya Rp1.600.000 + Rp595.000 = Rp2.195.000."],["Langkah","Bandingkan kombinasi yang memenuhi 130 kotak. Tiga Teratai: 150 kotak, Rp2.400.000. Dua Teratai dan satu Mawar: 135 kotak, Rp2.195.000. Dua Teratai dan dua Melati: 140 kotak, Rp2.360.000. Satu Teratai dan empat Melati: tepat 130 kotak, Rp2.320.000. Tiga Melati dan dua Mawar: tepat 130 kotak, Rp2.330.000. Kombinasi lain lebih mahal lagi. Termurah adalah dua Teratai dan satu Mawar. Kelebihan 5 kotak justru lebih hemat daripada memaksakan tepat 130."],["Kenapa opsi lain gugur",{"A":"Rp1.980.000 berasal dari 2 Teratai dan 1 Melati, yaitu 120 kotak. Murah, tetapi kurang 10 kotak dari kebutuhan.","B":"Rp2.080.000 adalah 130 × Rp16.000. Hitungan ini menganggap nasi kotak bisa dibeli satuan dengan harga Teratai, padahal katering hanya menjual paket.","D":"Rp2.320.000 berasal dari 1 Teratai dan 4 Melati, tepat 130 kotak. Pilihan ini terpaku pada angka tepat 130, padahal soal membolehkan lebih.","E":"Rp2.400.000 berasal dari 3 Teratai. Paketnya memang termurah per kotak, tetapi 20 kotak sisanya ikut dibayar."}],["Kunci","C, karena 2 paket Teratai dan 1 paket Mawar memberi 135 kotak dengan biaya Rp2.195.000, termurah di antara semua kombinasi yang cukup."],["Analogi","Seperti membeli air minum untuk acara. Kadang membeli sedikit lebih banyak dari kebutuhan dalam kemasan besar justru lebih murah daripada memaksakan jumlah pas dengan kemasan kecil."],["Jebakan","Ada dua godaan di soal ini: memaksakan tepat 130 kotak, dan memborong paket termurah per kotak. Bandingkan beberapa kombinasi yang memenuhi syarat, karena yang termurah sering berada di antara keduanya."]]},{"k":"A","b":[["Yang ditanya","gambar (5). Ada dua kelompok objek, dan masing-masing punya aturan sendiri."],["Cara cepat","Kelompok pertama: objek kanan atas tidak pernah pindah kotak. Ia hanya berputar 90° searah jarum jam setiap langkah. Kelompok kedua: tiga objek lain bergilir di tiga kotak sisanya (kiri atas → kanan bawah → kiri bawah), satu kotak setiap langkah, melompati kotak objek yang diam. Susunannya kembali seperti semula setiap tiga langkah. Gambar (5) adalah langkah keempat. Susunan tiga objek itu sama dengan gambar (2), sedangkan objek kanan atas sudah berputar penuh sehingga kembali seperti di gambar (1)."],["Kenapa opsi lain gugur",{"B":"tiga objek bergilir ke arah sebaliknya, kesalahannya: salah arah perpindahan.","C":"objek kanan atas dicermin, bukan diputar dan dua objek yang bergilir bertukar tempat, kesalahannya: mengganti putar dengan cermin sekaligus urutan giliran ikut berubah.","D":"tiga objek bergilir ke arah sebaliknya dan objek kanan atas sama dengan gambar (4), kesalahannya: salah arah perpindahan sekaligus lupa memutar objek kanan atas.","E":"objek kanan atas dicermin, bukan diputar, kesalahannya: mengganti putar dengan cermin."}],["Kunci","A, Opsi A memenuhi kedua kelompok aturan: susunan tiga objek seperti gambar (2) dan objek kanan atas kembali ke arah awal."],["Analogi","Seperti tiga orang yang bergiliran duduk di tiga kursi, sementara orang keempat tetap di kursinya dan hanya memutar badan seperempat putaran setiap kali."],["Jebakan","Jawabannya tidak sama dengan gambar mana pun yang terlihat. Kalau kamu menyalin gambar yang paling mirip, salah satu kelompok pasti keliru."]],"g":"assets/tiu-p1/TIU-P1-57-pembahasan.svg"},{"k":"E","b":[["Yang ditanya","gambar (6). Ada dua hal yang berubah, dan keduanya punya irama sendiri."],["Cara cepat","Bentuk besar (1), (2), (3) berbeda semua, jadi bentuk besar dibandingkan selang tiga: (1) dengan (4), (2) dengan (5). Keduanya diputar 90° berlawanan arah jarum jam, jadi bentuk besar di (6) = bentuk (3) yang diputar 90° berlawanan arah jarum jam. Bintik dihitung berurutan: 1, 2, 3, 4, 5. Bertambah satu setiap langkah, jadi gambar (6) punya 6 bintik. Letak bintik berpindah-pindah; yang dihitung hanya jumlahnya."],["Kenapa opsi lain gugur",{"A":"gambar (3) dicermin pada garis miring / dan bintiknya 7, kesalahannya: sesudah diubah, gambar ikut dicermin kiri-kanan sekaligus salah hitung lebih satu.","B":"gambar (3) dicermin pada garis miring \\ dan bintiknya 5, sama dengan gambar (5), kesalahannya: sesudah diputar, gambar ikut dicermin atas-bawah sekaligus lupa menambah bintik.","C":"gambar (3) dicermin pada garis miring /, kesalahannya: sesudah diubah, gambar ikut dicermin kiri-kanan.","D":"bintiknya 7, kesalahannya: salah hitung lebih satu."}],["Kunci","E, Opsi E satu-satunya yang bentuk besarnya diputar 90° berlawanan arah jarum jam dari gambar (3) dan bintiknya 6."],["Analogi","Seperti jadwal piket tiga hari yang berulang, sementara tanggal di kalender tetap maju satu hari setiap hari."],["Jebakan","Setelah menemukan pola selang tiga, banyak orang ikut menerapkannya pada bintik. Bintik punya irama sendiri: maju satu setiap langkah."]],"g":"assets/tiu-p1/TIU-P1-58-pembahasan.svg"},{"k":"C","b":[["Yang ditanya","gambar (4) supaya hubungan (1):(2) sama dengan (3):(4)."],["Cara cepat","Lihat pasangan yang lengkap, (1):(2). Ada tiga objek, dan setiap objek punya perubahannya sendiri. Gumpal berkelopak: 6 menjadi 4 kelopak, jadi berkurang 2. Bintang bercabang: 5 menjadi 8 cabang, jadi bertambah 3. Dua objek atas juga bertukar tempat: yang tadinya di kiri pindah ke kanan. Objek bawah dicermin atas-bawah. Terapkan ke gambar (3): kelopak 5 menjadi 3, cabang 7 menjadi 10, tukar tempatnya, lalu ubah objek bawah dengan cara yang sama."],["Kenapa opsi lain gugur",{"A":"ada 4 cabang (harusnya 10), kesalahannya: arah hitung cabang terbalik.","B":"kelopak tetap 5 dan ada 9 cabang (harusnya 10), kesalahannya: lupa mengubah jumlah kelopak sekaligus salah hitung kurang satu.","D":"ada 4 cabang (harusnya 10) dan objek bawah tidak berubah, kesalahannya: arah hitung cabang terbalik sekaligus lupa mengubah objek bawah.","E":"kelopak tetap 5 dan dua objek atas tidak bertukar tempat, kesalahannya: lupa mengubah jumlah kelopak sekaligus lupa menukar tempat."}],["Kunci","C, Opsi C satu-satunya yang jumlah kelopak dan cabangnya tepat, tempat objek atasnya benar, dan objek bawahnya dicermin atas-bawah."],["Analogi","Seperti tiga orang yang diberi tugas berbeda: satu menambah kelereng, satu membuang kelereng, satu hanya membalik badan. Tugas mereka tidak tertukar."],["Jebakan","Rupa kelopak dan cabang ikut berubah ketika jumlahnya berubah, jadi jangan mencocokkan rupa, cukup hitung. Opsi yang salah sering benar di dua hal dan keliru di hal lain, jadi periksa ketiga objek sampai selesai."]],"g":"assets/tiu-p1/TIU-P1-59-pembahasan.svg"},{"k":"B","b":[["Yang ditanya","gambar (2) supaya hubungan (1):(2) sama dengan (3):(4)."],["Cara cepat","Lihat pasangan yang lengkap, (3):(4). Periksa setiap objek sendiri-sendiri, jangan sekaligus. Objek kiri atas: diputar 90° searah jarum jam. Objek kanan atas: dicermin atas-bawah lalu dibalik warnanya. Objek bawah: dicermin kiri-kanan. Selain itu, objek kiri atas dan bawah bertukar tempat. Terapkan perubahan yang sama ke setiap objek di sel lawannya."],["Kenapa opsi lain gugur",{"A":"objek kiri atas dicermin pada garis miring \\ (harusnya diputar 90° searah jarum jam) dan objek bawah tidak berubah (harusnya dicermin kiri-kanan), kesalahannya: ikut dicermin kiri-kanan sekaligus objeknya dibiarkan tidak berubah.","C":"objek bawah tidak berubah (harusnya dicermin kiri-kanan), kesalahannya: objeknya dibiarkan tidak berubah.","D":"objek kiri atas diputar 90° berlawanan arah jarum jam (harusnya diputar 90° searah jarum jam) dan objek kanan atas dicermin atas-bawah (harusnya dicermin atas-bawah lalu dibalik warnanya), kesalahannya: salah arah putar atau cermin sekaligus salah soal balik warna.","E":"objek bawah dicermin atas-bawah (harusnya dicermin kiri-kanan) dan objek kiri atas dan objek bawah ada di tempat yang salah, kesalahannya: salah arah putar atau cermin sekaligus salah menerapkan tukar tempat."}],["Kunci","B, Opsi B satu-satunya gambar yang setiap objeknya berubah persis seperti pasangan contoh, termasuk tempatnya."],["Analogi","Seperti foto dan klisenya: bentuknya sama, terang dan gelapnya bertukar."],["Jebakan","Mata cepat menangkap perubahan warna lalu lupa memeriksa arah bentuknya. Cek dua hal itu di setiap objek."]],"g":"assets/tiu-p1/TIU-P1-60-pembahasan.svg"},{"k":"C","b":[["Yang ditanya","satu gambar yang isinya tidak mengikuti aturan keempat gambar lain."],["Cara cepat","Letak dan arah butir diacak di setiap gambar, jadi jangan mencari pola posisi atau putaran. Hitung tiap jenis butir. Jumlah satu jenis saja ternyata berubah-ubah di semua gambar, jadi aturannya bukan jumlah tetap. Bandingkan dua jenis sekaligus: di empat gambar, jumlah molekul 2 bulatan selalu sama dengan jumlah molekul 3 bulatan."],["Kenapa opsi lain gugur",{"A":"ada 2 molekul 2 bulatan dan 2 molekul 3 bulatan, jumlahnya sama.","B":"ada 4 molekul 2 bulatan dan 4 molekul 3 bulatan, jumlahnya sama.","D":"ada 4 molekul 2 bulatan dan 4 molekul 3 bulatan, jumlahnya sama.","E":"ada 2 molekul 2 bulatan dan 2 molekul 3 bulatan, jumlahnya sama."}],["Kunci","C, Hanya opsi C yang jumlahnya tidak sama: 3 molekul 2 bulatan dan 4 molekul 3 bulatan."],["Analogi","Seperti memeriksa pasangan sepatu di rak: jumlah sepatunya boleh berbeda di tiap rak, yang dicek apakah kiri dan kanannya selalu berpasangan."],["Jebakan","Kalau kamu hanya menghitung satu jenis, angkanya berubah-ubah dan kamu akan mengira soal ini tanpa pola. Polanya ada pada hubungan dua jenis."]],"g":"assets/tiu-p1/TIU-P1-61-pembahasan.svg"},{"k":"D","b":[["Yang ditanya","satu gambar yang salah satu objeknya tidak bisa didapat hanya dengan memutar."],["Cara cepat","Letak objek sama di kelima gambar, tetapi setiap objek diputar sendiri-sendiri. Gambar utuhnya tidak akan cocok satu sama lain, jadi jangan mencocokkan gambar sekaligus. Periksa per letak. Bandingkan objek besar di kiri di kelima gambar, lalu objek kecil kanan atas, lalu objek kecil kanan bawah. Di setiap letak, pilih satu ujung yang khas, lalu lihat apakah sisi kiri dan kanannya tertukar. Objek yang diputar tetap punya urutan sisi yang sama; objek yang dicermin urutannya terbalik."],["Kenapa opsi lain gugur",{"A":"ketiga objeknya hanya diputar, tidak ada yang dibalik, jadi masih sekelompok.","B":"ketiga objeknya hanya diputar, tidak ada yang dibalik, jadi masih sekelompok.","C":"ketiga objeknya hanya diputar, tidak ada yang dibalik, jadi masih sekelompok.","E":"ketiga objeknya hanya diputar, tidak ada yang dibalik, jadi masih sekelompok."}],["Kunci","D, Objek kecil kanan bawah di opsi D dibalik seperti bayangan cermin. Diputar ke arah mana pun, ia tidak bisa sama dengan objek kecil kanan bawah di empat gambar lain."],["Analogi","Seperti memeriksa lima tumpukan sarung tangan kanan yang diletakkan miring ke berbagai arah: arahnya boleh beda-beda, yang dicari satu sarung tangan kiri."],["Jebakan","Karena semua gambar tampak berbeda, mata mudah memilih gambar yang paling aneh susunannya. Yang menentukan hanya satu objek, dan objek itu bukan yang terbesar."]],"g":"assets/tiu-p1/TIU-P1-62-pembahasan.svg"},{"k":"A","b":[["Yang ditanya","sel kanan bawah matriks 3×3."],["Cara cepat","Setiap baris memakai satu bentuk, jadi bandingkan sel dalam baris yang sama. Dari kolom 1 ke kolom 2: diputar 90° searah jarum jam. Dari kolom 2 ke kolom 3: dicermin atas-bawah. Cek aturan itu di dua deret yang lengkap sebelum dipakai ke deret yang ada tanda tanyanya. Titik hitam punya aturan sendiri: pindah satu pojok searah jarum jam setiap sel."],["Kenapa opsi lain gugur",{"B":"bentuk benar, tetapi titik di pojok yang salah, titik pindah satu pojok searah jarum jam, jadi berada di kiri atas.","C":"langkah kedua tidak dikerjakan, padahal langkah kedua dicermin atas-bawah.","D":"bentuk dianggap kembali ke posisi awal, padahal perubahan terus berlanjut sampai sel terakhir.","E":"langkah kedua dicermin kiri-kanan, padahal langkah kedua dicermin atas-bawah."}],["Kunci","A, Opsi A mengikuti kedua langkah perubahan sampai sel terakhir, dan titiknya ada di pojok yang benar."],["Analogi","Seperti jarum jam yang terus maju: di jam ketiga jarumnya tidak kembali ke angka awal."],["Jebakan","Cermin atas-bawah dan cermin kiri-kanan mudah tertukar. Ikuti satu ujung bentuk: pada cermin atas-bawah ujung itu pindah dari atas ke bawah."]],"g":"assets/tiu-p1/TIU-P1-63-pembahasan.svg"},{"k":"B","b":[["Yang ditanya","sel kanan bawah. Bentuk dan letak objek kecil diacak, jadi yang dihitung hanya jumlahnya."],["Cara cepat","Hitung dua hal di setiap sel: cabang gumpal di tengah dan objek kecil di pinggir. Baris 1: 3/2, 4/3, 5/4 (cabang/objek kecil). Keduanya bertambah satu tiap kolom. Baris 3 mulai dari 5/6, 6/7, jadi sel terakhir 7 cabang dan 8 objek kecil. Cek lewat kolom 3: 5/4, 6/6, lalu 7/8. Selisihnya tetap, hasilnya sama."],["Kenapa opsi lain gugur",{"A":"objek kecil 7 (harusnya 8) dan cabang 8 (harusnya 7), kesalahannya: hitungan objek kecil kurang satu sekaligus hitungan cabang lebih satu.","C":"objek kecil 7 (harusnya 8), kesalahannya: hitungan objek kecil kurang satu.","D":"cabang 9 (harusnya 7), kesalahannya: hitungan cabang lebih dua.","E":"cabang 8 (harusnya 7) dan objek kecil 9 (harusnya 8), kesalahannya: hitungan cabang lebih satu sekaligus hitungan objek kecil lebih satu."}],["Kunci","B, Opsi B satu-satunya yang punya 7 cabang dan 8 objek kecil."],["Analogi","Seperti menghitung uang di dompet: bentuk koin dan letaknya tidak penting, jumlahnya yang dicek."],["Jebakan","Objek kecil berbentuk macam-macam supaya kamu sibuk mencari pola bentuk. Hitung saja semuanya, apa pun bentuknya."]],"g":"assets/tiu-p1/TIU-P1-64-pembahasan.svg"},{"k":"D","b":[["Yang ditanya","sel kanan bawah matriks 3×3."],["Cara cepat","Bandingkan per baris. Setiap sel punya satu objek besar dan satu bintang kecil, dan keduanya punya aturan sendiri. Objek besar: kolom 3 adalah gabungan objek besar kolom 1 dan kolom 2, ditumpuk di tempat yang sama. Bagian yang muncul di dua kolom sekaligus tetap ada, cukup sekali. Bintang kecil: kolom 3 memakai bintang kecil kolom 2, hanya ujungnya yang berubah dari lancip menjadi tumpul. Bintang kecil kolom 1 tidak dipakai. Cek dua aturan itu di baris 1 dan baris 2, lalu terapkan ke baris 3."],["Kenapa opsi lain gugur",{"A":"objek besarnya hanya salinan kolom 2 dan bintang kecilnya diambil dari kolom 1, kesalahannya: lupa menambahkan bagian dari kolom 1 sekaligus salah ambil kolom.","B":"objek besarnya hanya salinan kolom 1, kesalahannya: lupa menambahkan bagian dari kolom 2.","C":"ujung bintang kecilnya masih lancip dan bintang kecilnya diambil dari kolom 1, kesalahannya: lupa menumpulkan ujung sekaligus salah ambil kolom.","E":"objek besarnya hanya salinan kolom 1 dan bintang kecilnya diambil dari kolom 1, kesalahannya: lupa menambahkan bagian dari kolom 2 sekaligus salah ambil kolom."}],["Kunci","D, Opsi D satu-satunya yang objek besarnya gabungan utuh kolom 1 dan kolom 2, dan bintang kecilnya bintang kolom 2 yang ujungnya sudah tumpul."],["Analogi","Seperti menumpuk dua lembar plastik bening bergambar: semua gambar dari kedua lembar terlihat bersama dalam satu tumpukan."],["Jebakan","Bintang kecil kolom 1 dan kolom 2 sama-sama lancip dan mirip, jadi mudah salah ambil. Hitung cabangnya: yang dipakai selalu bintang kolom 2."]],"g":"assets/tiu-p1/TIU-P1-65-pembahasan.svg"},{"k":"E","p":{"A":4,"B":1,"C":2,"D":3,"E":5},"b":[["Yang ditanya","bayangkan para wali kelas di sekolahmu mengetik ulang nilai rapor satu per satu sampai larut, dan tetap saja ada yang salah ketik. Padahal aplikasi rapor punya fitur unggah dari templat. Kenapa tidak langsung dipakai? Karena wali kelas khawatir nilai satu kelas bisa salah masuk."],["Nilai tiap pilihan",{"E":"uji di satu kelas dulu, cocokkan dengan nilai aslinya, baru dipakai kelas lain. Wali kelas tidak perlu begadang lagi, dan rasa khawatir mereka dijawab dengan bukti, bukan janji.","A":"mulai dari kelas yang paling sering salah memang masuk akal. Hanya saja wali kelas yang lain masih mengetik sampai larut, padahal fitur yang sama bisa menolong mereka.","D":"hati-hati itu baik, cuma harganya mahal: satu semester lagi semua nilai diketik manual, dan salah ketiknya bisa terulang.","C":"rekan jadi nyaman, kerja tetap lambat. Salah ketiknya pun ikut bertahan.","B":"kasihan siswanya. Nilai rapor itu urusan wali kelas, bukan pekerjaan yang pantas dititipkan ke murid."}],["Kunci","E memakai teknologi yang sudah tersedia untuk mempercepat kerja, dengan hasil yang dicek dulu sebelum dipakai lebih luas."],["Analogi","kalau di rumah baru ada mesin cuci, kamu tidak langsung memasukkan semua baju putih dan berwarna. Kamu coba satu cucian dulu, lihat hasilnya, baru dipakai untuk semuanya."],["Jebakan","pilihan D paling sering dipilih orang yang takut salah. Padahal di cerita, cara lama pun sudah menghasilkan salah ketik. Menunda tidak membuatnya lebih aman."],["Tips","teknologi yang sudah ada di kantor biasanya dipakai, bukan dihindari. Yang membuatnya aman adalah uji kecil dan pengecekan hasil."]]},{"k":"C","p":{"A":3,"B":2,"C":5,"D":1,"E":4},"b":[["Yang ditanya","kamu yang mengatur antrean pencarian arsip. Lalu datang warga yang butuh salinan arsip tanah untuk sidang lusa, padahal pencarian biasanya makan tiga hari kerja. Ia cuma bilang secara lisan, dan ternyata dua pemohon lain juga dikejar tenggat minggu ini."],["Nilai tiap pilihan",{"C":"semua yang terdesak diminta bukti tenggatnya, lalu yang paling dekat didahulukan. Kalau sidang lusa itu terbukti, warga tadi tetap bisa paling dulu, dan dua pemohon lain tidak merasa dilangkahi.","E":"niatnya adil untuk semua yang terdesak. Masalahnya, cukup dengan mengaku. Besok semua orang bisa bilang sedang terdesak.","A":"surat panggilan sidang perlu diminta, setuju. Lalu bagaimana dengan dua pemohon lain yang juga dikejar waktu?","B":"urutan dijaga, sidang lusa dilupakan. Arsipnya bisa baru ketemu setelah sidang lewat.","D":"rapat bulan depan sudah terlambat jauh. Sidangnya lusa."}],["Kunci","C mendahulukan yang paling mendesak dengan satu ukuran yang sama untuk semua pemohon, yaitu bukti."],["Analogi","di IGD, pasien didahulukan menurut hasil pemeriksaan, bukan menurut siapa yang paling keras bilang sakit. Aturan itu berlaku untuk setiap pasien yang datang."],["Jebakan","kata \"antrean\" dan \"tiga hari kerja\" di pilihan B diambil persis dari soal, jadi terasa benar. Hitung saja: tiga hari kerja dari sekarang sudah lewat dari lusa."],["Tips","begitu ada lebih dari satu orang yang sama-sama terdesak, pakai satu ukuran untuk semuanya."]]},{"k":"A","p":{"A":5,"B":1,"C":2,"D":4,"E":3},"b":[["Yang ditanya","rekap kehadiran taruna harus kamu kirim siang ini, dan izin bermalam akhir pekan diputuskan dari rekap itu. Masalahnya, mesin presensi kosong untuk satu kelas. Untungnya dosen kelas itu mengisi daftar hadir manual, dan sebentar lagi ia selesai mengajar."],["Nilai tiap pilihan",{"A":"cukup tunggu sebentar, minta daftar hadir manualnya, lalu lengkapi rekap sebelum dikirim. Lubangnya ditutup tepat di kelas yang kosong, dan rekap tetap terkirim siang ini.","D":"tepat waktu, dan daftar hadirnya pun diambil dari dosen yang benar. Hanya urutannya terbalik: rekap sudah dipakai memutuskan izin bermalam sebelum susulan itu datang. Taruna kelas itu bisa kehilangan izin karena data yang sebenarnya ada.","E":"rapi sekali, tapi kebesaran. Mengumpulkan tanda tangan semua dosen lalu menyusun dari awal tidak akan selesai siang ini.","C":"saran senior terasa aman, padahal satu kelas taruna akan tercatat tidak hadir. Dosennya sendiri mencatat mereka hadir.","B":"menunggu mesin diperbaiki, entah kapan. Rekapnya bisa tidak terkirim sama sekali hari ini."}],["Kunci","A mengisi data yang kosong dari sumber yang sah, sebelum rekap itu dipakai untuk memutuskan izin."],["Analogi","ada satu halaman kosong di rapor yang mau dibagikan. Kamu minta halaman itu ke guru yang memegangnya, bukan membagikan dulu lalu menyusulkan, dan bukan mencetak ulang semua rapor."],["Jebakan","D tampak lengkap: tepat waktu, sumber datanya juga dosen kelas itu. Ia gugur karena urutan, sebab izin bermalam keburu diputuskan sebelum data susulan masuk."],["Tips","perhatikan kapan sebuah data dipakai. Data yang langsung dipakai untuk memutuskan sesuatu harus lengkap sebelum dikirim."]]},{"k":"B","p":{"A":1,"B":5,"C":4,"D":2,"E":3},"b":[["Yang ditanya","menjelang Natal, terminal ramai dan hampir semua petugas piketmu dibutuhkan. Rekan-rekan mengusulkan dua petugas yang merayakan Natal libur sepekan, padahal keduanya sendiri cuma butuh malam dan hari Natal. Lalu ingat, beberapa bulan lagi giliran rekan lain merayakan Idulfitri."],["Nilai tiap pilihan",{"B":"tanyakan dulu ke setiap petugas apa yang mereka butuhkan di hari besarnya, lalu susun tukar piket dari jawaban itu. Terminal tetap terjaga, dan saat Idulfitri tiba, caranya sudah siap.","C":"dua petugas itu libur persis sesuai kebutuhannya, dan piketnya pun terisi. Rapi untuk Natal tahun ini. Lalu bagaimana saat Idulfitri tiba? Kamu mengatur dari nol lagi, karena tidak ada cara yang disiapkan.","E":"niatnya adil untuk semua agama, dan itu patut dihargai. Sayangnya lamanya libur ditebak sendiri. Dua petugas itu tidak minta sepekan.","D":"suara terbanyak terdengar demokratis. Masalahnya, yang paling tahu kebutuhan dua petugas itu adalah mereka sendiri, dan mereka sudah bilang.","A":"mulia, kamu mau menanggung semua piket malam Natal. Jadwal piketnya sendiri tetap tidak tersusun, dan kamu bisa tumbang kelelahan."}],["Kunci","B bertanya dulu ke orang yang bersangkutan, lalu menyusun cara tukar piket yang bisa dipakai di setiap hari besar."],["Analogi","sebelum memesan makanan untuk acara kantor, kamu menanyakan pantangan tiap orang, bukan menebak sendiri. Daftarnya kamu simpan untuk acara berikutnya."],["Jebakan","kata \"tiap agama\" membuat E terdengar paling adil. Bandingkan dengan permintaan dua petugas itu: mereka cuma minta malam dan hari Natal, bukan sepekan."],["Tips","dalam urusan keberagaman, tanyakan dulu ke orang yang bersangkutan sebelum mengatur sesuatu untuk mereka."]]},{"k":"C","p":{"A":2,"B":1,"C":5,"D":4,"E":3},"b":[["Yang ditanya","rekan senior di loket sebelahmu menerima berkas keberatan tanpa tanda terima bernomor supaya antrean cepat, padahal SOP mewajibkannya. Ini sudah berjalan sejak Senin. Tadi pagi kamu menyinggungnya lewat candaan, tapi tak digubris, dan tiga pemohonnya masih menunggu."],["Nilai tiap pilihan",{"C":"ajak ia menerbitkan tanda terima yang tertinggal, lalu berdua cari cara supaya antrean tetap cepat tanpa melewati SOP. Tiga pemohon pulang membawa tanda terima, senior tidak dipermalukan, dan alasannya melanggar ikut hilang.","D":"tiga pemohon terlayani, dan rekanmu diingatkan soal SOP. Coba tanya dulu: kenapa ia melewati SOP sejak Senin? Supaya antrean cepat. Selama antrean masih menekan, permintaan kembali ke SOP gampang terlupa lagi.","E":"berani menegur langsung dan mencari jalan keluar. Sayang baru berlaku besok, sementara tiga orang yang sedang menunggu pulang tanpa tanda terima.","A":"candaan sudah dicoba dan tidak digubris. Mengulangnya cuma menjaga suasana, pelanggarannya jalan terus.","B":"antrean lancar enak dilihat, tapi kalau kamu ikut melanggar, pemohon yang dirugikan malah bertambah."}],["Kunci","C membereskan pemohon yang sedang menunggu dan alasan rekan melewati SOP, tanpa mempermalukan senior."],["Analogi","temanmu sering parkir sembarangan karena parkiran penuh. Kamu bantu memindahkan motornya sekarang, lalu kalian cari tempat parkir lain bersama."],["Jebakan","E dan C sama-sama \"menyepakati\" cara mempercepat antrean, jadi mudah tertukar. Pembedanya ada di tiga pemohon yang masih menunggu: E membiarkan mereka pulang tanpa tanda terima."],["Tips","kebiasaan yang berulang biasanya punya alasan. Jawaban terbaik menolong korban hari ini dan menghilangkan alasan itu."]]},{"k":"E","p":{"A":1,"B":4,"C":2,"D":3,"E":5},"b":[["Yang ditanya","kamu petugas verifikasi. Enam nama penerima bantuan benih belum kamu cek ke lapangan, jadi benih mereka tertahan sesuai aturan. Masa tanam mulai sepuluh hari lagi. Kelihatannya genting, tapi coba lihat angka yang satunya: pengecekan lapangan biasanya selesai dalam tiga hari."],["Nilai tiap pilihan",{"E":"datangi lahan keenam petani itu pekan ini. Waktunya masih cukup sebelum masa tanam, dan benih keluar kepada orang yang berhak.","B":"telepon terasa jauh lebih cepat, aku mengerti. Hanya saja lewat telepon kamu tidak bisa melihat lahannya, padahal waktu untuk datang langsung masih ada.","D":"surat pernyataan kelihatan resmi. Yang menjamin justru ketua kelompok, bukan kamu yang bertugas memverifikasi.","C":"aturannya terjaga, musim tanam petaninya hilang. Kasihan, padahal waktunya masih cukup untuk mengecek.","A":"kedengarannya membantu, tapi bantuan yang menjadi hak mereka malah tidak sampai."}],["Kunci","E menjalankan verifikasi sendiri, dengan waktu yang masih cukup sebelum masa tanam."],["Analogi","kalau dokter bisa memeriksamu hari ini, ia tidak akan memberi resep hanya dari cerita lewat telepon. Pemeriksaan langsung masih sempat dilakukan."],["Jebakan","kalimat \"agar benih cepat tersalur\" di B membuatnya terdengar peduli. Sepuluh hari dibanding tiga hari: buru-buru di sini sebenarnya tidak perlu."],["Tips","angka waktu di soal TKP jarang sekadar hiasan. Bandingkan tenggat dengan lama pekerjaannya sebelum memilih cara cepat."]]},{"k":"B","p":{"A":4,"B":5,"C":2,"D":3,"E":1},"b":[["Yang ditanya","musim ujian, dan ruang baca yang kamu koordinasikan penuh tas. Pelajar menandai meja lalu pergi berjam-jam, sementara lansia dan peneliti tidak kebagian tempat. Selama ini meja ditertibkan saat ada yang mengeluh, tapi begitu petugas pergi, tas-tas itu kembali."],["Nilai tiap pilihan",{"B":"pasang giliran paling lama tiga jam per meja selama ruang penuh. Pelajar tetap bisa belajar, pengunjung lain kebagian, dan aturan itu jalan tanpa harus menunggu ada yang mengeluh.","A":"lansia dan peneliti dipikirkan, itu manis. Lalu pengunjung lain? Meja lainnya tetap dikuasai tas yang ditinggal pemiliknya.","D":"cepat menanggapi keluhan, padahal cara ini sudah terbukti tak bertahan: petugas pergi, tas kembali.","C":"mengalah pada kelompok paling ramai terasa damai, sampai kamu sadar lansia dan peneliti yang harus mengalah setiap hari.","E":"kesepakatan antarpengunjung terdengar sopan, tapi siapa yang menjaganya kalau tas kembali ditinggal? Ruang ini punya koordinator, dan koordinatornya kamu."}],["Kunci","B membuat aturan pemakaian meja yang adil untuk semua pengunjung dan tetap jalan meski petugas tidak berjaga."],["Analogi","di warung yang ramai, cara paling adil adalah nomor antrean, bukan menegur orang yang menyerobot setiap kali ada pembeli yang protes."],["Jebakan","A paling mudah memikat orang yang berhati baik. Hanya saja sebab masalahnya, meja yang ditinggal berjam-jam, sama sekali tidak tersentuh."],["Tips","jawaban yang kuat menyentuh sebab masalah, bukan hanya menolong korbannya hari itu."]]},{"k":"A","p":{"A":5,"B":2,"C":3,"D":4,"E":1},"b":[["Yang ditanya","kamu baru ditugasi menyusun laporan dana kelurahan dengan format baru, tenggatnya tiga hari lagi. Staf yang dulu menyusunnya sudah dimutasi, tapi masih bisa ditelepon. Satu hal yang gampang terlewat: laporan ini wajib dibuat setiap triwulan."],["Nilai tiap pilihan",{"A":"minta dibimbing lewat telepon, lalu catat langkah-langkahnya jadi panduan seksi. Laporan kali ini selesai, dan triwulan depan kamu, atau siapa pun di seksi, tidak perlu menelepon lagi.","D":"laporannya pasti beres. Hanya saja bagian tersulit dikerjakan orang lain, dan triwulan depan kamu harus memintanya lagi, padahal ia sudah pindah tempat kerja.","C":"mau belajar sendiri itu sikap yang bagus. Yang berisiko adalah laporan keuangan langsung dikirim tanpa diperiksa: kalau ada yang keliru, tidak ada yang sempat menangkapnya.","B":"wajar merasa belum siap. Tugasnya sudah di tanganmu, dan ada orang yang bisa membimbing.","E":"kenapa menolak bantuan? Mengerjakan sendirian tidak membuat laporannya lebih benar."}],["Kunci","A menyelesaikan laporan sekarang dengan bimbingan orang yang paham, dan menyimpan caranya untuk triwulan berikutnya."],["Analogi","saat diajari masak rendang oleh nenek, kamu mencatat resepnya. Kamu tidak menyuruh nenek memasak setiap Lebaran."],["Jebakan","untuk tiga hari ini, D paling cepat dan paling aman. Soalnya menyebut \"setiap triwulan\", dan di triwulan depan D tidak menolongmu."],["Tips","pekerjaan yang berulang menuntut jawaban yang tetap berguna di putaran berikutnya."]]},{"k":"C","p":{"A":3,"B":2,"C":5,"D":1,"E":4},"b":[["Yang ditanya","kamu sedang memimpin apel, lalu seorang penguji senior bilang sambil tertawa bahwa pemilik kendaraan dari satu suku yang suka membantah sebaiknya \"dipersulit ramai-ramai saja, tidak usah pakai aturan\". Beberapa penguji muda ikut tertawa. Ini sudah bukan sekadar candaan, karena isinya mengajak berlaku tidak adil kepada satu suku."],["Nilai tiap pilihan",{"C":"tegur ucapan itu di depan apel, dan tegaskan bahwa aturan berlaku sama untuk kendaraan siapa pun. Penguji muda yang tadi tertawa langsung mendengar mana yang benar, dan seniornya tidak diserang secara pribadi.","E":"berani menegur langsung, tapi apel keburu bubar, jadi penguji muda yang tertawa tidak ikut mendengar. Lagi pula, kok sudah yakin ia benci? Itu baru tebakan.","A":"menegur senior memang tidak enak. Masalahnya, kamu sendiri yang memimpin apel. Kenapa harus menunggu kepala balai?","B":"suasana tetap cair, dan teguran pribadi nanti tidak pernah didengar penguji muda. Mereka pulang dengan kesan bahwa ucapan seperti itu boleh.","D":"kasihan penguji muda itu, dibiarkan menebak sendiri sikap mana yang benar, padahal pemimpinnya ada di depan mereka."}],["Kunci","C meluruskan ucapan itu di tempat ia diucapkan, di depan orang yang mendengarnya."],["Analogi","kalau ada teman yang menulis hal keliru di grup kelas, pelurusannya juga ditulis di grup itu, bukan lewat pesan pribadi esok harinya."],["Jebakan","teguran empat mata di E terasa paling sopan. Yang perlu mendengar bukan cuma si senior, tapi juga penguji muda yang ikut tertawa."],["Tips","menegur di depan orang banyak tidak harus mempermalukan. Tegaskan aturannya, jangan serang orangnya."]]},{"k":"C","p":{"A":1,"B":2,"C":5,"D":4,"E":3},"b":[["Yang ditanya","seorang ibu kembali karena label sirup anaknya tertulis 3 &times; 2 sendok, padahal resepnya 3 &times; 1. Yang menulis rekanmu, dan ia yakin sudah teliti. Sekarang pun ia masih menulis label untuk puluhan resep yang mengantre, dengan cara yang sama."],["Nilai tiap pilihan",{"C":"betulkan dulu label sirup itu, lalu cocokkan setiap label dengan resepnya sebelum obat diserahkan. Antrean tetap jalan, dan kalau ada salah tulis lagi, ketahuan sebelum sampai ke tangan pasien.","D":"label ibu beres, rekan diingatkan. Ia sudah merasa teliti, ingat? Disuruh lebih cermat tidak mengubah apa-apa kalau tidak ada yang mengecek.","E":"niatnya menolong rekan yang mungkin lelah. Itu baru tebakan, dan kalau semua label kamu tulis sendiri, antrean jadi lambat.","B":"menjaga perasaan rekan itu baik hati. Sampai antrean sepi, puluhan label sudah ditulis dengan cara yang sama.","A":"tambahan tenaga mungkin perlu, nanti. Label yang salah masih di tangan ibu itu sekarang."}],["Kunci","C membetulkan kesalahan yang sudah terjadi dan memasang pengecekan untuk setiap obat yang keluar."],["Analogi","kasir yang pernah salah memberi kembalian tidak cukup berjanji lebih teliti. Ia menghitung ulang uangnya di depan pembeli sebelum menyerahkannya."],["Jebakan","D mirip cara kita biasa mengingatkan teman, jadi terasa wajar. Kata kuncinya ada di soal: rekan itu \"yakin sudah teliti\"."],["Tips","dalam urusan obat, pengecekan sebelum diserahkan lebih penting daripada mencari siapa yang salah."]]},{"k":"E","p":{"A":2,"B":1,"C":3,"D":4,"E":5},"b":[["Yang ditanya","bayangkan kamu lansia yang dalam sepekan dikunjungi dua petugas berbeda dan harus menceritakan hal yang sama dua kali. Itulah keluhan belasan keluarga di soal ini. Lalu ada satu fakta penting: data bidang sebelah baru diperbarui pusat bulan lalu, sedangkan datamu dari pendataan tahun lalu."],["Nilai tiap pilihan",{"E":"cocokkan dulu daftar keluarga kedua bidang, baru susun jadwal kunjungan gabungan. Dari situ ketahuan semua keluarga yang tumpang tindih, termasuk yang belum sempat mengeluh.","D":"kunjungan gabungan itu ide yang tepat, cuma terbatas pada yang sudah mengeluh. Datamu dan data bidang sebelah beda versi, jadi bisa saja masih ada keluarga lain yang dikunjungi dua kali.","C":"berbagi daftar itu bagus, hanya daftarmu justru yang lebih lama. Kalau dijadikan acuan, keluarga di data baru bisa terlewat.","A":"kesal kalau kerja jadi dobel, wajar. Tapi kok sudah yakin mereka tidak mau berbagi? Itu baru dugaan, dan langsung dibawa ke atasan pula.","B":"kasihan keluarga itu. Mereka sudah lelah, lalu malah diminta bersabar tanpa ada yang berubah."}],["Kunci","E menyamakan data dua bidang dulu, lalu menyusun satu jadwal yang menolong semua keluarga."],["Analogi","dua kurir dari satu toko mengantar ke perumahan yang sama. Sebelum rutenya digabung, alamat di catatan masing-masing dicocokkan dulu, karena salah satu catatan sudah lama."],["Jebakan","D langsung menolong yang mengeluh, dan itu yang membuatnya menarik. Lihat umur kedua data: keluarga yang belum mengeluh bisa saja ikut dikunjungi dua kali."],["Tips","kerja sama antarbidang dimulai dari data yang sama, bukan dari jadwal."]]},{"k":"D","p":{"A":2,"B":4,"C":1,"D":5,"E":3},"b":[["Yang ditanya","rekan sekantor menyerahkan lima berkas tetangganya ke loketmu saat kuota hampir habis. Katanya mereka sudah ambil nomor, tapi tak satu pun kartunya dibawa. Ingat juga, bulan lalu warga memprotes titipan serupa di loket lain."],["Nilai tiap pilihan",{"D":"berkas itu tidak ditolak, tapi masuk antrean umum dan dicocokkan dengan nomor seperti berkas warga lain. Kalau mereka sudah antre, nomornya akan ketemu. Kalau belum, mereka antre seperti orang lain.","B":"tegas dan sesuai aturan. Lima warga di balik berkas itu ikut tertolak tanpa dicek, padahal bisa jadi mereka sudah antre.","E":"melarang titipan di semua loket itu langkah besar. Anehnya, lima berkas ini tetap diproses hanya karena kata rekanmu, padahal kartunya tidak ada.","A":"menolak rekan sendiri itu tidak enak, aku paham. Warga yang sudah antre bisa terlangkahi, dan protes bulan lalu bisa terulang.","C":"menunggu arahan kepala dinas, padahal kamu sendiri yang berwenang mengatur antrean? Sementara itu kuota hari ini terus berkurang."}],["Kunci","D memperlakukan berkas titipan sama dengan berkas warga lain, diperiksa lewat nomor antreannya."],["Analogi","temanmu titip lima nama di antrean tiket konser. Petugas yang baik tidak mengusir temanmu. Ia meminta semua nama masuk barisan dan mencocokkan tiketnya dengan nomor antrean."],["Jebakan","B tegas dan ada aturan tertempelnya, jadi terasa benar. Pikirkan lima warga di balik berkas itu, yang mungkin tidak tahu apa-apa soal titipan."],["Tips","adil artinya satu cara periksa untuk semua orang, termasuk kenalan rekan sendiri."]]},{"k":"B","p":{"A":1,"B":5,"C":2,"D":3,"E":4},"b":[["Yang ditanya","kamu sedang merekap proposal kelompok tani yang tenggatnya tiga hari lagi, lalu antivirus memberi peringatan saat flashdisk salah satu kelompok dicolokkan. Dinas punya pengelola jaringan untuk perangkat bermasalah. Ada juga pelajaran dari bulan lalu: komputer bidang sebelah tetap tertular walau sudah dibersihkan sendiri."],["Nilai tiap pilihan",{"B":"bawa flashdisk itu ke petugas jaringan, lalu kabari kelompoknya bahwa berkas mereka sedang diperiksa. Yang memeriksa orang yang bertugas, dan proposal mereka tidak hilang dari daftar.","E":"flashdisk disingkirkan dan proposal tetap masuk lewat surel. Rapi. Masalahnya, flashdisk itu sudah sempat masuk ke komputermu. Siapa yang memeriksa komputernya?","D":"mereka yang membawa, mereka yang membersihkan. Kedengarannya adil, sampai kamu ingat bulan lalu: dibersihkan sendiri pun tetap tertular. Petaninya juga harus bolak-balik.","C":"bertanya ke rekan itu wajar, hanya jawaban \"biasa kok\" tidak membuat flashdisk itu aman.","A":"memperbarui antivirus memang perlu, tapi flashdisk bermasalah itu tetap tergeletak tanpa ada yang menangani."}],["Kunci","B menyerahkan perangkat bermasalah ke petugas yang memang mengurusnya, tanpa membuat proposal petani terbengkalai."],["Analogi","kalau tabung gas di rumah berbau bocor, kamu memanggil petugas gas. Tetanggamu pernah mencoba memperbaikinya sendiri, dan tetap bocor."],["Jebakan","banyak yang memilih E karena flashdisk-nya disingkirkan. Padahal antivirus baru berbunyi setelah flashdisk dicolokkan, jadi komputernya juga perlu diperiksa."],["Tips","kerusakan yang pernah gagal dibereskan sendiri di kantormu adalah tanda kuat untuk memanggil petugasnya."]]},{"k":"A","p":{"A":5,"B":3,"C":1,"D":2,"E":4},"b":[["Yang ditanya","rekan instruktur las di BLK-mu kerap meninggalkan peserta memakai mesin las tanpa pendamping. Dua kali kamu sudah menegurnya langsung, tapi ia tetap mengulang, dan kemarin seorang peserta luka bakar. Tugas instruktur diatur kepala seksi, dan angkatan ini masih berjalan dua bulan."],["Nilai tiap pilihan",{"A":"laporkan kebiasaan itu ke kepala seksi, lengkap dengan catatan tanggal tiap kejadian. Orang yang mengatur tugas instruktur jadi tahu, buktinya jelas, dan rekanmu tidak dipermalukan di depan peserta.","E":"rela menjaga kelasnya sendiri, itu sungguh baik hati. Hitung saja: dua bulan lagi. Selama itu kamu harus selalu siaga, sementara kebiasaannya tidak berubah.","B":"mencatat kejadian itu cermat. Tapi menunggu ada peserta terluka lagi? Luka bakar kemarin sudah cukup jadi alasan.","D":"kesal karena teguranmu tidak digubris, aku paham. Teguran ketiga yang lebih keras di depan peserta cuma mempermalukannya, padahal dua teguran sebelumnya pun tidak mempan.","C":"hubungan baik memang penting, tapi keselamatan peserta tidak bisa diserahkan pada kesadaran yang sudah dua kali diuji."}],["Kunci","A membawa masalah ke orang yang berwenang mengatur tugas instruktur, setelah teguran langsung gagal dan sudah ada korban."],["Analogi","teman kosmu berkali-kali lupa mematikan kompor. Sudah dua kali kamu ingatkan, dan kemarin panci sampai gosong. Sekarang kamu bilang ke pemilik kos, bukan terus menjaga kompor itu sendirian."],["Jebakan","E membuatmu jadi pahlawan kelas, dan justru itu godaannya. Angkatan ini masih dua bulan; selama itu kebiasaan rekanmu tetap jalan."],["Tips","lapor atasan bukan langkah pertama, tapi juga bukan pengkhianatan. Ia tepat setelah cara langsung gagal dan ada yang terluka."]]},{"k":"D","p":{"A":4,"B":1,"C":3,"D":5,"E":2},"b":[["Yang ditanya","di ruang ganti perawat tertempel pamflet yang menuding satu kelompok agama sebagai ancaman negara, dan fotonya sudah beredar di grup ruangan. Kamu kepala ruang yang mengelola papan pengumuman dan grup itu. Dua perawat dari kelompok tersebut mengaku tidak nyaman."],["Nilai tiap pilihan",{"D":"copot pamfletnya, hapus fotonya dari grup, lalu temui dua perawat itu. Penyebarannya berhenti di tangan orang yang mengelola papan dan grup, dan rekan yang terluka hatinya tidak dibiarkan sendirian.","A":"pamfletnya kamu copot, bagus. Tapi foto di grup dan dua perawat itu kamu serahkan ke kepala bidang, padahal grupnya kamu sendiri yang kelola. Selama menunggu beliau, fotonya terus diteruskan.","C":"ingin tahu siapa pelakunya, wajar sekali. Selama kamu mencari, foto itu terus beredar.","E":"foto hilang dari grup, pamflet masih menempel di ruang ganti. Dua perawat itu masih bisa melihatnya.","B":"di luar urusan pelayanan, betul. Kasihan dua rekanmu yang merasa tidak nyaman di tempat kerjanya sendiri."}],["Kunci","D menghentikan pamflet dan sebarannya saat itu juga, lalu memperhatikan rekan yang terdampak."],["Analogi","ada coretan menghina di dinding kelas yang kamu jaga. Kamu hapus dulu, lalu menanyakan kabar teman yang dihina. Kamu tidak menunggu surat dari kepala sekolah untuk menghapusnya."],["Jebakan","A terdengar lengkap: pamflet dicopot, foto dan dua perawat juga diurus. Yang terlupa, kamu sendiri pemegang papan dan grup itu, jadi tidak perlu menunggu atasan."],["Tips","menghentikan sebaran dan menemui yang terluka bisa dilakukan dalam beberapa menit. Laporan ke atasan boleh menyusul."]]},{"k":"E","p":{"A":3,"B":2,"C":4,"D":1,"E":5},"b":[["Yang ditanya","kamu petugas laboratorium. Hasil dahak TBC baru jadi tiga hari kerja, tapi pendaftaran selalu bilang ke pasien \"kembali besok\". Akibatnya banyak pasien datang sia-sia, dan dua di antaranya sampai menyewa perahu dari desa seberang."],["Nilai tiap pilihan",{"E":"duduk bersama pendaftaran, sepakati tanggal ambil untuk setiap pasien, dan kabari kalau hasilnya mundur. Informasinya tetap keluar dari meja pendaftaran, isinya sekarang benar.","C":"pasien yang sudah datang jadi tahu kapan kembali, dan itu baik. Pasien besok pagi? Mereka masih akan mendengar \"kembali besok\".","A":"pasien seberang tertolong. Pasien yang rumahnya dekat juga datang sia-sia, dan mereka tidak masuk hitungan.","B":"pengumuman itu baru terbaca setelah pasien sampai di depan laboratorium. Ongkos perahunya sudah keluar.","D":"secara aturan, informasi memang urusan pendaftaran. Yang menanggung ruginya tetap pasien laboratoriummu."}],["Kunci","E membereskan sumber keterangan yang keliru, dan berlaku untuk tiap pasien, bukan hanya yang telanjur datang."],["Analogi","kalau papan petunjuk jalan salah arah, menjemput satu per satu orang yang tersesat itu baik. Membetulkan papannya jauh lebih menolong."],["Jebakan","pilihan C terasa paling peduli: pasien ditelepon satu per satu. Kata \"telanjur\" di situ sudah menjawab, karena yang ditolong hanya yang sudah rugi."],["Tips","kalau masalahnya datang dari keterangan yang salah, perbaiki keterangannya sebelum sibuk menolong korbannya."]]},{"k":"D","p":{"A":1,"B":4,"C":3,"D":5,"E":2},"b":[["Yang ditanya","seorang sopir cerita ke kamu, koordinator jaga terminal, bahwa petugas jaga malam sering memutar ceramah yang menyebut pemerintah tidak sah lewat pengeras suara pos. Sopir itu sendiri cuma dengar dari rekan sesama pengemudi."],["Nilai tiap pilihan",{"D":"teruskan cerita itu ke unit pengawasan internal, lengkap dengan asal kabarnya: dari sopir, yang dengar dari sopir lain. Biar mereka yang mengecek. Kamu bergerak cepat tanpa menghakimi siapa pun.","B":"kedengarannya hati-hati, cuma dipindah, tidak dihukum. Coba posisikan dirimu sebagai petugas itu: gilirannya digeser karena cerita yang belum pernah dicek.","C":"semua petugas di semua pos ikut kena larangan, sementara yang dibicarakan cuma satu orang, dan itu pun baru kabar.","E":"menegur langsung berarti kamu sudah menganggap kabar itu benar. Kalau ternyata salah, kamu yang harus minta maaf.","A":"menjauhi orang karena kabar burung sama saja menghukum tanpa sidang. Rekan-rekan ikut kamu ajak pula."}],["Kunci","D menanggapi kabar dengan cepat lewat pihak yang berwenang mengecek, tanpa menjatuhkan tindakan apa pun sebelum terbukti."],["Analogi","dengar kabar seorang warga mencuri? Kamu tidak menggeledah rumahnya. Kamu sampaikan ke pengurus RT, lengkap dengan siapa yang bercerita."],["Jebakan","kalimat penentunya ada di tengah cerita: \"hanya mendengarnya dari rekan sesama pengemudi\". Pilihan yang langsung menegur atau memindahkan petugas melompati kalimat itu."],["Tips","di soal paham anti-pemerintah, ukur dulu seberapa kuat buktinya. Kabar dari mulut ke mulut diteruskan untuk dicek, bukan ditindak."]]},{"k":"A","p":{"A":5,"B":3,"C":4,"D":1,"E":2},"b":[["Yang ditanya","kamu memandu rapat penerima bantuan pangan, dan daftarnya disahkan hari ini juga. Seorang kepala dusun bercanda agar keluarga pendatang yang berbeda keyakinan dicoret saja, dan peserta tertawa. Candaan serupa tadi sudah kamu alihkan."],["Nilai tiap pilihan",{"A":"sela candaannya dan ingatkan semua orang: bantuan dinilai dari kelayakan, bukan keyakinan. Daftar belum disahkan, dan yang ikut tertawa mendengar langsung dari pemimpin rapatnya.","C":"ralatnya diminta di depan forum yang sama, dan itu bagus. Masalahnya jam: daftar sudah disahkan ketika ralat itu datang. Keluarga pendatang itu sudah ditimbang sambil semua orang membawa candaan tadi di kepalanya.","B":"camat tidak ada di ruangan. Yang memimpin rapat ini kamu sendiri.","E":"tadi sudah dialihkan, dan candaannya muncul lagi. Kalau diulang, hasilnya kemungkinan sama.","D":"kamu repot sendiri, keluarga itu tidak perlu hadir, dan ucapan tadi tetap tidak dibantah siapa pun."}],["Kunci","A meluruskan dasar penilaian saat itu juga, di depan semua yang ikut tertawa, sebelum daftar disahkan."],["Analogi","wasit yang melihat pelanggaran langsung meniup peluit. Kalau baru ditegur sesudah pertandingan, skornya sudah tercatat."],["Jebakan","mengalihkan pembicaraan tampak cerdik karena tidak ada yang tersinggung. Cara itu sudah dipakai tadi, dan candaannya kembali."],["Tips","kalau keputusan diambil di ruangan itu juga, teguran yang ditunda sama dengan diam."]]},{"k":"E","p":{"A":1,"B":2,"C":3,"D":4,"E":5},"b":[["Yang ditanya","kepala bidang penagihan sedang di luar kantor dan minta rekap penunggak pajak malam ini. Isinya NIK dan nomor telepon. Berkasnya terlalu besar untuk surel dinas, jadi ia menyarankan lewat aplikasi pesan, padahal data itu hanya boleh dibuka pejabat penagihan."],["Nilai tiap pilihan",{"E":"unggah ke penyimpanan daring kantor dan atur aksesnya khusus untuk kepala bidang. Malam ini juga rekapnya bisa ia buka, dan orang lain tidak bisa.","D":"rekapnya sampai malam ini, setuju. Sepanjang jalan, flashdisk berisi NIK warga itu ada di saku orang lain, dan bisa jatuh atau tersalin.","C":"permintaan hapus itu datang belakangan. Begitu terkirim, berkasnya sudah tersimpan di aplikasi pesan.","B":"berkasnya terlalu besar, dan mencoba lagi tidak mengubah ukurannya.","A":"rekap diminta malam ini. Besok pagi permintaannya sudah lewat."}],["Kunci","E memenuhi permintaan atasan malam ini tanpa membuka data ke orang yang tidak berhak."],["Analogi","barang berharga lebih aman dikirim lewat loker yang hanya bisa dibuka penerimanya daripada dititipkan ke kenalan yang kebetulan lewat."],["Jebakan","sarannya datang dari atasan sendiri, jadi aplikasi pesan terasa sudah diizinkan. Soal ini justru menguji apakah kamu ingat batas data itu: hanya untuk pejabat penagihan."],["Tips","untuk saran atasan soal cara kirim, kamu boleh menawarkan jalan lain, asal tujuannya tetap tercapai."]]},{"k":"E","p":{"A":4,"B":1,"C":2,"D":3,"E":5},"b":[["Yang ditanya","kamu koordinator pendaftaran. Beberapa pasien perempuan pulang sebelum diperiksa: setelah antre lama, mereka menolak dokter laki-laki karena keyakinan. Padahal ada dokter perempuan di sif pagi, dan pengumumannya sudah menempel di ruang tunggu sejak awal bulan."],["Nilai tiap pilihan",{"E":"tanyakan di loket, mau diperiksa dokter laki-laki atau perempuan. Pasien langsung masuk antrean dokter pilihannya, tidak perlu menunggu lama lalu pulang.","A":"kamu turun tangan, dan pasiennya akhirnya diperiksa. Sayang, ia sudah antre lama di antrean yang salah.","D":"pengumuman sudah menempel sejak awal bulan, dan pasien tetap pulang. Memperbesar hurufnya tidak menjamin pasien membacanya.","C":"dokter perempuannya ada di sini, di sif pagi. Kenapa pasien harus pergi ke puskesmas lain?","B":"aturan antrean dipakai untuk menyuruh pasien pulang. Ia datang untuk berobat."}],["Kunci","E menghormati keyakinan pasien sejak di loket, dan urutan antrean tetap sama untuk semua."],["Analogi","warung yang bertanya \"pedas atau tidak?\" waktu memesan tidak perlu membuang makanan yang ditolak di meja."],["Jebakan","di pilihan A ada usaha nyata: kamu sendiri yang mengantar. Usaha itu datang setelah pasien antre lama, dan antre lama itulah yang membuat pasien pulang."],["Tips","kalau keluhan selalu muncul di ujung antrean, cari pertanyaan yang bisa diajukan di awal."]]},{"k":"C","p":{"A":3,"B":1,"C":5,"D":4,"E":2},"b":[["Yang ditanya","sudah dua bulan RSUD mengirim berkas kelahiran ke dinasmu setiap Jumat, supaya akta terbit tanpa orang tua harus datang. Tiga Jumat terakhir, belasan berkas datang tanpa surat keterangan lahir. Kamu belum pernah membicarakannya dengan mereka."],["Nilai tiap pilihan",{"C":"temui petugas rekam medis, sepakati daftar periksa berkas, lalu lengkapi yang sudah tertunda. Kiriman Jumat depan lengkap, dan akta yang tertahan ikut jalan.","D":"tegas, dan akta tetap terbit dari berkas yang lengkap. Hanya saja, rumah sakit menerima berkas kembali tanpa tahu apa yang kurang, karena belum pernah ada yang bilang. Jumat depan bisa terulang.","A":"evaluasi itu bagus, tapi bulan depan berarti masih ada beberapa Jumat lagi berkas datang kurang.","E":"kerja sama ini dibuat supaya orang tua tidak perlu repot. Pilihan ini malah membuat mereka repot.","B":"rumah sakit tidak akan sadar kalau tidak ada yang memberi tahu."}],["Kunci","C membicarakan kekurangan langsung dengan mitra dan memberinya alat yang jelas, sambil menyelesaikan akta yang tertunda."],["Analogi","kalau tukang laundry terus lupa melipat, kamu bilang saja caranya. Mengembalikan baju tiap minggu tanpa penjelasan hanya membuat kalian sama-sama capek."],["Jebakan","mengembalikan berkas yang kurang terlihat tegas dan benar. Rumah sakit \"belum pernah\" diberi tahu, jadi mereka tidak tahu apa yang harus diperbaiki."],["Tips","sebelum menilai mitra lalai, tanya dulu: sudah pernah diberi tahu belum?"]]},{"k":"D","p":{"A":3,"B":4,"C":1,"D":5,"E":2},"b":[["Yang ditanya","seorang warga keberatan didenda karena bukunya tercatat terlambat. Ia yakin sudah memasukkannya ke kotak pengembalian sebelum jatuh tempo. Kamu koordinator sirkulasi yang berwenang menghapus denda keliru, dan setiap sore rekanmu mencatat isi kotak itu."],["Nilai tiap pilihan",{"D":"buka catatan rekanmu di lembar pengosongan, cocokkan tanggalnya. Kalau cocok, batalkan dendanya saat itu juga. Warga lega, dan kamu punya dasar.","B":"ada niat memeriksa, itu bagus. Hanya alamatnya meleset: catatan isi kotak ada di meja sirkulasi, bukan di bagian TI.","A":"warga langsung senang. Bagaimana kalau besok sepuluh orang lain datang dengan keyakinan yang sama?","E":"kepala perpustakaan pasti bisa memutuskan. Hanya saja wewenang itu sudah ada di tanganmu.","C":"disuruh melunasi dulu, lalu keberatannya masuk kotak saran. Warga pulang dengan perasaan tidak didengar."}],["Kunci","D mengecek bukti yang ada di unitmu sendiri, lalu memakai wewenangmu dengan dasar yang jelas."],["Analogi","kasir yang ditegur pembeli soal kembalian tidak langsung menyerahkan uang, dan tidak juga memanggil manajer. Ia membuka struk dan menghitung ulang."],["Jebakan","melibatkan kepala perpustakaan kesannya paling aman. Soal sudah menyebut kamu \"berwenang menghapus denda keliru\", jadi menyerahkannya ke atas berarti melepas tugasmu sendiri."],["Tips","sebelum menyerahkan ke pihak lain, cek dulu catatan apa yang sudah ada di unitmu sendiri."]]},{"k":"C","p":{"A":1,"B":4,"C":5,"D":3,"E":2},"b":[["Yang ditanya","kemarin kamu mengirim siaran pers capaian imunisasi ke belasan redaksi. Pagi ini bidang program bilang angkanya keliru, dan seorang wartawan sudah menelepon karena angkanya beda dengan dasbor resmi. Mengaku salah ke semua redaksi tentu malu rasanya."],["Nilai tiap pilihan",{"C":"kirim ralat ke semua redaksi yang kemarin menerima siaran, lalu jawab wartawan itu. Malu sebentar, dan tidak ada media yang memuat angka keliru dari instansimu.","B":"rapi dan resmi, tapi cuma satu wartawan yang dapat angka benar. Redaksi lain masih memegang angka kemarin.","D":"angkanya memang dari bidang program. Siaran persnya kamu yang kirim, jadi ralat paling pas keluar dari kamu juga.","E":"laman instansi diam-diam berubah, sementara berita dengan angka lama bisa tetap terbit. Kalau ketahuan, malunya jauh lebih besar.","A":"yang tidak bertanya dibiarkan memuat angka keliru."}],["Kunci","C membereskan kekeliruan di semua tempat angka itu terkirim, lewat jalur yang sama dengan siaran kemarin."],["Analogi","kalau undangan yang tersebar salah tanggal, kamu kirim ralat ke semua penerima, bukan hanya menjawab tamu yang kebetulan bertanya."],["Jebakan","rasa malu di kalimat terakhir cerita sengaja dipasang. Pilihan yang paling sedikit malunya, A dan E, justru yang paling merugikan."],["Tips","ralat dikirim lewat jalur yang sama dan ke penerima yang sama dengan kabar yang keliru."]]},{"k":"E","p":{"A":4,"B":3,"C":1,"D":2,"E":5},"b":[["Yang ditanya","kamu menyusun dokumen pengadaan laptop: delapan untuk administrasi, dua untuk menyunting video. Spesifikasinya cuma bilang \"prosesor setara atau lebih tinggi\", tanpa menyebut setara dengan apa. Padahal penyedia langsung menyusun penawaran dari dokumen yang diumumkan Senin."],["Nilai tiap pilihan",{"E":"tanya bidang perencanaan hari ini juga, maksudnya setara dengan apa. Senin masih aman, dan penyedia membaca dokumen yang jelas.","A":"jadwal aman. Hanya saja, saat sesi tanya jawab dibuka, sebagian penyedia sudah menghitung harga dari spesifikasi yang kabur.","B":"staf baru diminta menebak maksud orang lain dari katalog merek. Yang tahu maksudnya ada di bidang perencanaan.","D":"menyalin apa adanya terasa aman buatmu. Penyedia tetap bingung harus menawarkan laptop yang mana.","C":"dua laptop untuk menyunting video disamakan dengan laptop administrasi. Anggarannya rata, kebutuhannya tidak."}],["Kunci","E menanyakan maksud spesifikasi ke sumbernya sebelum dokumen dibaca penyedia, sementara jadwal Senin masih terkejar."],["Analogi","pesanan kue tertulis \"rasa seperti biasa\"? Telepon dulu pemesannya sebelum oven menyala, bukan setelah kuenya jadi."],["Jebakan","ada dua jenis laptop di cerita. Kalau kamu melewatkan angka delapan dan dua itu, pilihan C terlihat hemat dan wajar."],["Tips","dokumen yang langsung dipakai pihak luar harus jelas sebelum keluar. Pertanyaan sesudahnya selalu lebih mahal."]]},{"k":"D","p":{"A":1,"B":4,"C":2,"D":5,"E":3},"b":[["Yang ditanya","setiap bulan kamu merekap laporan kunjungan enam relawan sukarela untuk usulan bantuan lansia. Bentuk laporannya macam-macam, dan dua relawan sudah tiga bulan berturut-turut terlambat sepekan. Jumat ini ada pertemuan rutin dengan mereka semua."],["Nilai tiap pilihan",{"D":"manfaatkan pertemuan Jumat: sepakati satu format singkat dan tenggat kirim bersama-sama. Relawan ikut menentukan aturannya, jadi lebih mudah ditepati.","B":"rekapmu jadi rapi dalam satu format, dan laporan yang telat tertagih. Bulan depan? Kamu menagih dan menyalin lagi, karena relawan tetap menulis dengan caranya masing-masing.","E":"dua relawan yang terlambat beres. Empat lainnya tetap mengirim dengan bentuknya masing-masing.","C":"surat edaran di grup gampang terbaca, gampang juga dilupakan. Format yang macam-macam pun tidak disentuh.","A":"menghargai relawan itu penting. Kalau tidak ada yang berubah, usulan bantuan lansia ikut berantakan."}],["Kunci","D membereskan dua masalah, bentuk dan tenggat, untuk semua relawan, dengan cara yang membuat mereka merasa dilibatkan."],["Analogi","pengurus arisan yang setoran anggotanya macam-macam tidak menagih satu per satu. Mereka sepakati bersama tanggal dan caranya di pertemuan berikutnya."],["Jebakan","cerita menyebut dua masalah. Pilihan E dan C hanya menjawab keterlambatan, padahal bentuk laporan yang berbeda-beda ada di keenam relawan."],["Tips","hitung berapa masalah yang disebut cerita, lalu cari pilihan yang menjawab semuanya."]]},{"k":"B","p":{"A":1,"B":5,"C":2,"D":4,"E":3},"b":[["Yang ditanya","dua kali bulan ini puluhan anak menunggu dongeng Sabtu di perpustakaanmu, dan pendongengnya tidak datang. Ketua komunitas sudah meneruskan jadwal, tapi ternyata dua pendongeng itu tidak pernah menerima pesannya."],["Nilai tiap pilihan",{"B":"sepakati dengan ketua komunitas: setiap pendongeng membalas konfirmasi ke kamu sebelum Kamis. Kalau sampai Kamis belum ada balasan, kamu masih punya waktu mencari jalan.","D":"jadwal sebulan penuh terlihat rapi. Jadwal serapi apa pun percuma kalau pesannya tidak sampai ke pendongeng.","E":"anak-anak tetap mendengar dongeng, dan Sabtu itu selamat. Pekan berikutnya kamu harus siap lagi, karena pesan yang hilang tidak diperbaiki.","C":"komunitas ini bekerja tanpa dibayar. Surat yang menagih kewajiban bisa terasa seperti teguran, sementara salahnya ada di pesan yang tidak sampai.","A":"film kartun mengisi waktu anak-anak. Pendongengnya tetap tidak tahu jadwal."}],["Kunci","B menutup celah yang sebenarnya, yaitu pesan yang tidak sampai, dengan cara yang ringan bagi relawan."],["Analogi","kalau undangan sering nyasar, minta tamu membalas \"hadir\" lebih dulu. Dari balasan itu kamu tahu siapa yang belum menerima."],["Jebakan","kata \"ternyata\" di kalimat kedua memberi tahu letak masalahnya. Jadwalnya ada, yang macet pesannya."],["Tips","kalau sebuah rencana gagal, tanyakan dulu: rencananya yang salah, atau kabarnya yang tidak sampai?"]]},{"k":"A","p":{"A":5,"B":3,"C":2,"D":1,"E":4},"b":[["Yang ditanya","sejak surel wajib verifikasi dua langkah, tiga staf di ruang arsip bawah tanah tidak bisa bekerja, karena kodenya dikirim ke ponsel dan di sana tidak ada sinyal. Penguat sinyal baru terpasang bulan depan. Unit TI tempatmu bekerja masih menyimpan kunci keamanan USB cadangan."],["Nilai tiap pilihan",{"A":"daftarkan alat verifikasi fisik itu untuk mereka bertiga hari ini. Mereka bisa membuka surel dari ruang arsip, dan keamanannya tidak berkurang sedikit pun.","E":"kerja tetap jalan, tapi bayangkan sebulan naik-turun tangga setiap kali butuh kode. Waktu kerja mereka habis di tangga.","B":"pengecualian berarti pintu yang tadinya dikunci dibuka lagi, padahal alat penggantinya sudah ada di unit TI.","C":"kode verifikasi itu rahasia. Begitu dibacakan lewat telepon, ada orang lain yang ikut tahu.","D":"aman sih, tapi ketiga staf itu jadi tidak bisa bekerja sama sekali sampai bulan depan."}],["Kunci","A memulihkan kerja tiga staf hari ini dengan alat yang sudah tersedia, tanpa melonggarkan keamanan."],["Analogi","kalau kartu akses kantormu tertinggal, satpam memberimu kartu tamu. Pintunya tetap terkunci untuk orang lain, dan kamu tetap bisa masuk."],["Jebakan","hampir semua pilihan sibuk mengakali sinyal. Jalan keluarnya justru tersimpan di unit TI sendiri: alat yang tidak butuh sinyal sama sekali."],["Tips","sebelum minta pengecualian aturan, cek dulu alat apa yang sudah ada di tanganmu."]]},{"k":"C","p":{"A":4,"B":2,"C":5,"D":1,"E":3},"b":[["Yang ditanya","kamu koordinator PKL di enam bengkel yang menampung siswamu tanpa bayaran. Dua pemilik bengkel mengeluh: lembar penilaian selalu datang mepet, bentuknya ganti tiap semester, dan ada kolom yang tidak mereka pahami. Semester depan, empat mitra baru bergabung."],["Nilai tiap pilihan",{"C":"ajak perwakilan bengkel merumuskan satu format penilaian yang tetap, sekalian jadwal kirimnya. Mitra paham isinya karena ikut menyusun, dan empat bengkel baru tinggal memakainya.","A":"kamu rajin sekali. Sekarang hitung: enam bengkel, semester depan sepuluh, dan bentuk lembarnya masih berganti-ganti.","E":"idenya sudah benar, waktunya yang telat. Begitu semester depan berjalan, sepuluh bengkel sudah menerima lembar yang membingungkan.","B":"minta maaf itu baik. Tanpa perubahan cara, lembar berikutnya datang mepet lagi.","D":"guru pembimbing kenal siswanya, tapi keluhan bengkel soal lembar penilaian tetap tidak ada yang mengurus."}],["Kunci","C menjawab ketiga keluhan dengan melibatkan mitra, dan siap dipakai sebelum mitra bertambah."],["Analogi","kalau tamu sering bingung mengisi buku tamu, kamu tidak menunggui mereka satu per satu. Kamu perbaiki kolomnya, lalu semua tamu bisa mengisi sendiri."],["Jebakan","kalimat \"Semester depan ada empat mitra baru\" terlihat seperti tambahan. Kalimat itulah yang membuat cara A, mendatangi tiap bengkel, cepat kewalahan."],["Tips","kalau jumlah mitra akan bertambah, pilih cara yang tetap jalan tanpa kamu harus hadir di setiap tempat."]]},{"k":"D","p":{"A":3,"B":1,"C":2,"D":5,"E":4},"b":[["Yang ditanya","cuma kamu yang memverifikasi surat pindah di kantor kecamatan, dengan puluhan berkas sehari, dan kamu boleh mengatur jam loket. Senin ini sekretaris camat memberimu tugas mendata ulang ratusan barang dalam dua pekan. Ia tidak tahu verifikasi itu hanya kamu yang mengerjakan."],["Nilai tiap pilihan",{"D":"ceritakan dulu beban loketmu ke sekretaris camat, lalu sepakati jam layanan dan jam mendata. Atasan jadi tahu keadaannya, dan dua pekerjaan punya waktunya masing-masing.","E":"kamu berusaha mengerjakan keduanya tanpa mengeluh. Hanya saja, saat jadwal sudah tertinggal, ruang untuk mengatur ulang tinggal sedikit.","A":"berkas mendesak terlayani, yang lain menunggu dua pekan. Padahal setiap warga datang dengan urusannya masing-masing.","C":"perintah atasan dipatuhi, tapi loket surat pindah tutup sampai pendataan selesai. Atasanmu pun tidak pernah meminta loket ditutup.","B":"pelayanan warga dijadikan alasan menolak tugas, padahal keduanya masih bisa dijalankan kalau jamnya diatur."}],["Kunci","D memberi atasan informasi yang belum ia punya, lalu mengatur waktu agar kedua tugas jalan."],["Analogi","kalau dosen memberi tugas besar di pekan ujian tanpa tahu jadwalmu, kamu bilang dari awal dan atur tenggatnya bersama, bukan mengeluh di hari terakhir."],["Jebakan","bekerja diam-diam tanpa mengeluh sering dianggap terpuji. Di soal ini atasan \"tanpa tahu\" bebanmu, dan diam membuatnya tetap tidak tahu sampai jadwal tertinggal."],["Tips","kalau atasan memberi tugas tanpa tahu bebanmu, beri tahu bebanmu sebelum mulai mengerjakan."]]},{"k":"B","p":{"A":2,"B":5,"C":4,"D":1,"E":3},"b":[["Yang ditanya","KTP-el seorang pedagang patah, padahal besok pagi ia harus tanda tangan pencairan pinjaman di bank. Blanko kosong sampai pekan depan, dan cadangannya disisihkan untuk korban bencana. Surat keterangan pengganti bisa dibuat, tapi butuh tanda tangan kepala seksi yang cuma ada sampai sore."],["Nilai tiap pilihan",{"B":"proses surat keterangan penggantinya sekarang dan kejar tanda tangan kepala seksi sebelum sore. Pedagang pulang membawa bukti identitas, blanko untuk korban bencana tetap utuh.","C":"suratnya sudah siap, tinggal tanda tangan. Masalahnya, besok pagi pedagang harus sudah di bank, bukan menunggu di kantormu.","E":"KTP-el barunya pasti jadi, tapi pekan depan. Pencairannya besok pagi.","A":"kebijakan khusus dari kepala dinas butuh waktu, padahal jalan keluarnya sudah ada di meja kepala seksi.","D":"memeriksa rekaman biometrik tidak salah, hanya tidak menolong pedagang yang besok pagi harus ke bank."}],["Kunci","B memakai jalur resmi yang sudah tersedia dan menyelesaikannya sebelum batas waktunya habis."],["Analogi","kehabisan tiket kereta? Petugas tidak memberimu kursi yang disimpan untuk penumpang darurat. Ia mencarikan jadwal lain yang masih mengantarmu tepat waktu."],["Jebakan","pilihan C dan B hampir sama isinya. Bedanya ada di kapan tanda tangan diminta, dan kalimat \"hanya ada sampai sore\" yang menentukan."],["Tips","kalau dua pilihan berisi langkah yang sama, bandingkan waktunya dengan batas yang disebut cerita."]]},{"k":"E","p":{"A":3,"B":2,"C":4,"D":1,"E":5},"b":[["Yang ditanya","kamu mengatur rapat penjelasan tender hari Rabu, dan hanya di rapat itu peserta bisa tanya jawab. Seorang calon penyedia minta jadwal digeser karena hari itu Galungan. Peserta lain sudah memesan tiket dari luar kota. Untungnya, sistem tender bisa menyiarkan rapat dan menerima pertanyaan tertulis."],["Nilai tiap pilihan",{"E":"rapat tetap Rabu, jadi tiket peserta lain tidak sia-sia. Penyedia yang beribadah bisa menonton siarannya, dan pertanyaannya ditampung sampai Jumat bersama pertanyaan peserta lain. Tidak ada yang dirugikan.","C":"penjelasannya sampai ke dia, itu bagus. Sayangnya rekaman tidak bisa ditanya. Kalau ada yang belum jelas, ke mana ia bertanya?","A":"niatnya menghormati hari rayanya. Hanya saja peserta yang sudah memegang tiket untuk hari Rabu ikut menanggung akibatnya. Kebaikan untuk satu orang berubah jadi beban bagi yang lain.","B":"ia baru meminta, belum berbuat apa-apa, dan sudah dicurigai. Meminta bukti hari raya sama saja dengan meragukan keyakinan orang.","D":"kedengarannya adil karena semua diperlakukan sama. Sama rata tidak selalu setara: yang satu kehilangan kesempatan bertanya karena ibadahnya."}],["Kunci","E menjaga jadwal untuk semua orang dan tetap membuka jalan bertanya bagi yang berhalangan."],["Analogi","seperti kuliah yang disiarkan dan punya kolom tanya daring: mahasiswa yang berhalangan tetap ikut belajar dan bertanya, tanpa jadwal kelas dipindah untuk semua."],["Jebakan","wajar kalau kamu langsung memilih menggeser jadwal, karena terasa paling menghormati. Di cerita ada peserta yang sudah membeli tiket, dan ada sistem yang bisa menyiarkan rapat. Dua fakta itu membuat menggeser jadwal jadi pilihan yang lebih mahal dari yang perlu."],["Tips","bayangkan dirimu di posisi setiap orang di cerita, termasuk peserta yang sudah membeli tiket, sebelum memutuskan siapa yang harus berkorban."]]},{"k":"A","p":{"A":5,"B":1,"C":2,"D":3,"E":4},"b":[["Yang ditanya","berkas kenaikan pangkat seorang guru dari pulau sudah lengkap, tinggal legalisir fotokopi SK terakhir. SK aslinya ada di pulau, batasnya Jumat, dan kapal baru datang Sabtu. Arsip SK ada di bagianmu, dan kepala subbagian yang berwenang melegalisir sedang di kantor."],["Nilai tiap pilihan",{"A":"salinan SK-nya ada di arsipmu sendiri, dan orang yang berhak melegalisir ada di kantor yang sama. Berkas lengkap hari itu juga, guru itu tidak perlu menyeberang lagi.","E":"niatmu menolong, dan fotokopinya pun sudah kamu cocokkan dengan arsip. Masalahnya, tanda tangan legalisir bukan wewenangmu, sementara yang berwenang justru ada di kantor.","D":"terdengar luwes. Sayang hitungannya tidak cocok: SK asli baru bisa dibawa Sabtu, sedangkan batasnya Jumat.","C":"aturannya kamu pegang, dan guru itu pulang dengan tangan kosong. Kekurangannya sebenarnya bisa ditutup dari kantormu sendiri.","B":"kasihan guru itu, disuruh pulang menyeberang, lalu urusannya dititipkan ke kerabat yang tidak memegang SK aslinya."}],["Kunci","A menutup kekurangan berkas dengan arsip dan pejabat yang sudah ada di kantor, sebelum batas Jumat."],["Analogi","seperti fotokopi ijazah yang ketinggalan: kalau kampusmu menyimpan salinannya dan bagian akademik bisa mengesahkannya hari itu, kamu tidak perlu pulang kampung untuk mengambil yang asli."],["Jebakan","siapa yang berhak membubuhkan legalisir? Pertanyaan ini sering terlewat saat kamu ingin cepat menolong. Cerita menjawabnya sendiri: kepala subbagian, dan ia sedang di kantor."],["Tips","sebelum menyuruh warga kembali lagi, periksa apa yang sebenarnya sudah tersimpan di kantormu sendiri."]]},{"k":"D","p":{"A":3,"B":1,"C":4,"D":5,"E":2},"b":[["Yang ditanya","kamu instruktur kelas otomotif di balai latihan kerja, dan kamu juga yang menyusun tata tertibnya. Dari evaluasi tanpa nama, ketahuan tiga peserta dari luar daerah tertinggal karena teman kelompoknya memberi arahan dalam bahasa daerah. Kelompok juga sering praktik di bengkel tanpa kamu dampingi."],["Nilai tiap pilihan",{"D":"semua peserta ikut memutuskan, jadi aturannya terasa milik mereka sendiri. Begitu tertulis di tata tertib, aturan itu tetap berjalan walau kamu tidak ada di bengkel.","C":"isinya sudah benar. Bayangkan kelompok yang bekerja di bengkel tanpa instruktur: aturan yang hanya diumumkan dari depan kelas mudah terlupa. Menyebut peserta luar daerah sebagai alasannya juga bisa membuat mereka makin canggung.","A":"arahnya bagus, cuma terlambat. Sampai evaluasi akhir bulan depan, tiga peserta itu terus tertinggal.","E":"kenapa yang disuruh menyesuaikan justru tiga orang yang sudah tertinggal? Mereka datang untuk belajar otomotif, bukan bahasa daerah.","B":"target praktik kelompok tercapai, dan tiga orang tetap tertinggal. Membebaskan di sini sama dengan membiarkan."}],["Kunci","D mengubah kebiasaan lewat kesepakatan bersama, lalu mengikatnya di tata tertib yang kamu susun."],["Analogi","seperti kelompok tugas yang sepakat memakai bahasa yang dipahami semua anggota karena ada teman dari kota lain. Tidak perlu guru yang mengawasi setiap obrolan."],["Jebakan","pilihan C dan D sama-sama memakai bahasa Indonesia, jadi godaannya memilih yang paling cepat. Pembedanya ada di kalimat terakhir cerita: kelompok sering bekerja tanpa kamu. Aturan yang hanya diumumkan butuh pengawas, aturan yang disepakati dijaga sendiri oleh pesertanya."],["Tips","kalau dua pilihan isinya sama, bandingkan cara aturannya lahir: diputuskan sendiri atau disepakati bersama."]]},{"k":"B","p":{"A":3,"B":5,"C":2,"D":1,"E":4},"b":[["Yang ditanya","seseorang yang mengaku petugas puskesmas datang membawa surat tugas. Ia minta daftar lansia lengkap dengan NIK dan nomor telepon. Kamu operator data desa, dan kantor menyimpan nomor resmi puskesmas. Bulan lalu desa tetangga tertipu surat tugas palsu dengan cara yang sama."],["Nilai tiap pilihan",{"B":"kamu menelepon puskesmas lewat nomor yang disimpan kantormu sendiri. Kalau benar, program jalan. Kalau palsu, data lansia aman. Kepala desa juga tahu apa yang terjadi.","E":"kamu sudah berhati-hati, sayang yang ditelepon nomor dari surat itu sendiri. Kalau suratnya palsu, nomornya bisa saja milik komplotan yang sama.","A":"data memang tidak keluar dari mejamu. Hanya saja orang yang sama tinggal datang ke ketua RT, yang tidak punya cara memeriksanya.","C":"rekanmu mungkin tahu sesuatu, mungkin juga tidak. Yang dibutuhkan di sini pemeriksaan, bukan ingatan.","D":"berkasnya aman di laci, tapi tidak ada yang selesai. Lansia menunggu, dan petugas itu pun belum jelas asli atau palsu."}],["Kunci","B memeriksa lewat jalur yang tidak bisa dikendalikan oleh si peminta."],["Analogi","dapat telepon dari \"bank\" yang meminta kode OTP? Kamu tidak menelepon balik nomor yang ia berikan. Kamu menelepon nomor di balik kartu ATM-mu."],["Jebakan","langkah memastikan di pilihan E membuatnya mirip kunci. Bedanya hanya di nomor mana yang ditelepon. Kejadian di desa tetangga mengingatkan bahwa surat tugas bisa dipalsukan, berikut nomor yang tertulis di dalamnya."],["Tips","kejadian buruk di tempat lain yang disebut cerita biasanya menunjukkan cara kerja penipunya. Pakai itu untuk menguji setiap pilihan."]]},{"k":"B","p":{"A":4,"B":5,"C":1,"D":3,"E":2},"b":[["Yang ditanya","kamu bertugas di BPBD, yang mengirim peringatan ketinggian air ke grup lima kepala desa di hilir. Banjir pekan lalu, dua desa terlambat mengungsi karena kepala desanya telat membaca pesan, dan belum ada yang tahu sebabnya. Kamu sendiri hanya piket dua malam dalam sepekan."],["Nilai tiap pilihan",{"B":"setiap desa memilih sendiri siapa yang menerima, dan orang itu wajib membalas. Begitu ada balasan, kamu tahu pesannya sampai, siapa pun yang sedang piket malam itu.","A":"kamu sungguh peduli, sampai mau menelepon satu per satu. Lalu bagaimana di malam-malam saat kamu tidak piket?","D":"instruksi camat bisa membuat kepala desa lebih waspada. Masalahnya, kamu belum tahu kenapa mereka telat, jadi instruksinya bisa meleset dari sebab yang sebenarnya.","E":"menegur di depan grup sebelum tahu sebabnya? Bisa jadi ada alasan yang belum kamu dengar.","C":"setara bukan berarti mengulang cara yang pekan lalu terbukti terlambat."}],["Kunci","B memperbaiki jalur penerimaan peringatan bersama desa, sehingga tidak bergantung pada satu orang."],["Analogi","seperti paket kiriman yang meminta tanda terima: pengirim tidak perlu menelepon penerima setiap hari, karena tanda terima sudah memberi tahu barangnya sampai."],["Jebakan","menelepon satu per satu kelihatan penuh tanggung jawab. Kalimat pendek di akhir cerita yang menggugurkannya: kamu hanya ada dua malam sepekan, sedangkan hujan deras tidak menunggu jadwal piket."],["Tips","solusi yang baik tetap berjalan saat kamu libur, sakit, atau sedang tidak bertugas."]]},{"k":"C","p":{"A":1,"B":4,"C":5,"D":2,"E":3},"b":[["Yang ditanya","kamu penyuluh yang masih baru. Hasil ukur GPS-mu menunjukkan luas tanam tiga desa jauh di bawah angka yang dimasukkan rekan senior ke laporan tim. Laporan itu dikirim Jumat dan menjadi dasar pembagian pupuk bersubsidi. Rekan senior itu ada di kantor hari ini."],["Nilai tiap pilihan",{"C":"datangi rekanmu hari ini dan bahas selisihnya selagi laporan belum terkirim. Angka yang keliru bisa dibetulkan, dan seniormu tidak merasa dilangkahi.","B":"orangnya sudah tepat, rekan senior itu sendiri. Hanya saja waktunya terlambat: begitu laporan terkirim Jumat, pupuk dibagi memakai angka yang keliru.","E":"kamu sudah berani bicara langsung ke orangnya. Sayang lewat pesan, dan kalimat \"tampak keliru\" bisa terbaca seperti tuduhan dari orang baru. Ia ada di kantor, kenapa tidak bicara berdua?","D":"kepala bidang bisa menahan laporan, sementara rekanmu belum tahu ada selisih. Ia bisa merasa dilaporkan sebelum diberi kesempatan.","A":"aku paham rasa sungkan sebagai orang baru. Diam di sini berarti pupuk dibagi memakai angka yang kamu tahu tidak cocok dengan lapangan."}],["Kunci","C membawa data ke orang yang memasukkan angka itu, selagi masih ada waktu membetulkannya."],["Analogi","melihat teman salah menulis nomor rekening di formulir kelompok? Kamu bilang padanya sebelum formulir diserahkan, bukan lapor ke guru atau menunggu uangnya salah kirim."],["Jebakan","sebagai orang baru, menunggu laporan terkirim lebih dulu terasa paling sopan. Kalimat \"dikirim Jumat sebagai dasar pembagian pupuk bersubsidi\" membuat kesopanan itu mahal, karena pembagian pupuk di tiga desa itu ikut keliru."],["Tips","rasa sungkan pada senior itu wajar. Yang membuat pembicaraan tetap nyaman adalah membawa data, bukan tuduhan."]]},{"k":"A","p":{"A":5,"B":4,"C":3,"D":2,"E":1},"b":[["Yang ditanya","kamu admin aplikasi surat keterangan daring di kecamatan, dan kamu boleh mengubah tampilan aplikasinya. Selama sepekan uji coba, puluhan pengajuan ditolak karena foto kartu keluarga lebih dari 2 MB. Bulan depan loket kertas ditutup, dan kebanyakan warga mengirim dari rumah."],["Nilai tiap pilihan",{"A":"petunjuknya muncul tepat di tempat warga akan mengunggah. Sebelum gagal, mereka sudah tahu batasnya dan cara mengecilkan fotonya, di mana pun mereka mengirim.","B":"warga akhirnya tahu aturannya, sesudah ditolak, dan tetap belum tahu cara mengecilkan fotonya. Pengajuan berikutnya bisa gagal lagi.","C":"warga yang datang tertolong, dan itu baik. Yang mengirim dari rumah, dan mereka justru kebanyakan, tidak kebagian bantuanmu.","D":"loket kertas yang dibuka terus terasa aman. Hanya saja masalah foto 2 MB tetap ada, tinggal ditunda.","E":"warga yang sudah gagal sekali masih harus mencari jasa di luar. Perbaikannya sebenarnya ada di tanganmu sebagai admin."}],["Kunci","A memperbaiki tempat masalahnya muncul, yaitu halaman unggah, sehingga semua pemohon terbantu sebelum gagal."],["Analogi","toko daring yang sering menerima keluhan ukuran baju salah tidak membalas satu per satu. Ia memasang tabel ukuran di halaman produknya."],["Jebakan","menjawab setiap pengajuan yang ditolak itu rajin. Lihat urutannya: warga gagal dulu, baru diberi tahu. Sebagai admin yang boleh mengubah tampilan, kamu bisa mencegah gagalnya, bukan hanya menjelaskannya."],["Tips","perhatikan di mana kebanyakan orang di cerita berada. Bantuanmu harus sampai ke tempat itu."]]},{"k":"B","p":{"A":4,"B":5,"C":1,"D":2,"E":3},"b":[["Yang ditanya","dalam tiga apel Senin terakhir, seorang rekan di bagianmu tetap duduk saat Indonesia Raya dinyanyikan. Beberapa pegawai mulai berbisik bahwa ia menolak negara, padahal belum ada yang mengajaknya bicara. Ia sendiri tidak pernah menyampaikan pandangan apa pun. Yang ditanya: langkah pertamamu."],["Nilai tiap pilihan",{"B":"tanyakan langsung, berdua saja. Kamu mendapat jawaban dari orangnya, bukan dari bisik-bisik, dan ia tidak dipermalukan di depan siapa pun.","A":"lapor ke kepala bagian itu jalur yang benar, hanya belum waktunya. Bayangkan ternyata ia punya alasan yang belum diketahui siapa pun, dan namanya sudah sampai ke meja atasan.","E":"aturannya benar, tempatnya keliru. Ditegur di depan barisan, ia lebih mungkin malu atau melawan daripada bercerita.","D":"niatnya mengumpulkan informasi, hasilnya bisik-bisik makin ramai.","C":"membela orang yang alasannya belum kamu tahu sama berisikonya dengan menuduhnya."}],["Kunci","B mencari tahu dari sumbernya, dengan cara yang tidak mempermalukan."],["Analogi","teman sekelasmu tiba-tiba tidak mau ikut upacara? Sebelum ikut membicarakannya, kamu tanya dia baik-baik di jam istirahat."],["Jebakan","bisik-bisik di cerita bisa ikut memengaruhimu. Pisahkan yang dilihat sendiri, yaitu rekan itu duduk, dari yang hanya ditebak orang, yaitu ia menolak negara."],["Tips","kata \"langkah pertama\" meminta tindakan paling awal yang masuk akal, bukan tindakan paling keras."]]},{"k":"D","p":{"A":4,"B":2,"C":3,"D":5,"E":1},"b":[["Yang ditanya","kamu staf desa yang mengatur peminjaman balai, siapa cepat dia dapat. Majelis taklim dan kelompok arisan biasa memesan sebulan sebelumnya, sehingga persekutuan doa keluarga Kristen dan sanggar tari warga pendatang belum sekali pun kebagian tahun ini. Pengurus keduanya mengeluh kepadamu."],["Nilai tiap pilihan",{"D":"aturannya dibenahi bersama, bukan ditambal. Setiap kelompok punya giliran, termasuk yang selama ini kalah cepat memesan.","A":"kedua kelompok akhirnya dapat tempat, dan itu kemajuan. Hanya saja mereka tetap menjadi penerima malam sisa yang jarang dipesan orang.","C":"majelis taklim diminta mengalah, dan itu pun hanya bulan ini. Bulan depan, urutannya kembali seperti semula.","B":"warga yang puas adalah warga yang selama ini kebagian. Dua kelompok yang mengeluh juga bagian dari warga.","E":"kasihan pengurusnya, sudah mengeluh langsung kepadamu tapi masih disuruh menulis surat keberatan dulu."}],["Kunci","D membuat balai benar-benar bisa dipakai bergiliran oleh semua warga."],["Analogi","seperti lapangan sekolah yang selalu dipakai tim basket karena mereka paling cepat mendaftar. Jalan keluarnya jadwal giliran, bukan menyuruh tim lain bermain di jam yang tidak diminati siapa pun."],["Jebakan","ada yang berbagi di pilihan C, jadi kesannya adil. Lihat siapa yang berkorban dan untuk berapa lama: satu kelompok, satu bulan, lalu masalahnya kembali."],["Tips","aturan yang terasa adil bagi kebanyakan orang perlu dicek dari sisi kelompok yang paling jarang kebagian."]]},{"k":"A","p":{"A":5,"B":2,"C":4,"D":3,"E":1},"b":[["Yang ditanya","unit TI-mu akan memasang pembaruan keamanan server, dan aplikasi layanan mati enam jam. Vendor menawarkan Sabtu pagi atau sore, yang menurut catatan paling sepi, asal jamnya dikunci Rabu. Bidang perizinan, salah satu dari tiga pemakai aplikasi, biasa menjadwalkan pemohon sepekan sebelumnya."],["Nilai tiap pilihan",{"A":"kamu tidak menebak jadwal orang lain, kamu menanyakannya. Perizinan bisa menunjuk jam yang sudah terisi pemohon, dan jam tetap terkunci sebelum Rabu.","C":"catatan menunjukkan kebiasaan masa lalu. Yang tidak tercatat di sana: pemohon yang mungkin sudah dijadwalkan perizinan untuk Sabtu itu.","D":"ketiga bidang diberi tahu, sesudah semuanya diputuskan. Kalau jam itu bentrok dengan pemohon perizinan, sudah tidak bisa diubah.","B":"hubungan baik dengan vendor itu penting. Pilihan jamnya tetap harus ditimbang dari layanan, bukan dari rasa sungkan.","E":"aplikasi mati enam jam dalam sekali jalan kedengarannya berat. Dipecah tiga pekan, gangguannya malah datang tiga kali, dan pembaruan keamanannya tertunda."}],["Kunci","A mengajak pemakai aplikasi ikut memilih jam, dan tetap selesai sebelum batas Rabu."],["Analogi","seperti pengelola gedung yang akan mematikan listrik: ia menawarkan dua pilihan jam ke para penyewa dulu, baru memutuskan."],["Jebakan","keputusan berdasarkan catatan kesannya paling objektif. Perhatikan data apa yang dipakai: catatan tentang ramai-sepinya aplikasi. Jadwal pemohon perizinan hanya diketahui bidang itu sendiri, dan cara mengetahuinya adalah bertanya."],["Tips","data lama membantu menebak, orang yang terdampak memberi kepastian."]]},{"k":"A","p":{"A":5,"B":4,"C":1,"D":2,"E":3},"b":[["Yang ditanya","kamu staf humas yang mengatur siaran langsung di radio tentang tarif retribusi. Separuh acaranya tanya jawab lewat telepon, dan hanya kepala bidang pendapatan yang boleh menjawab. Jadwal di rencana kerja humas jatuh pada Jumat Agung, hari ibadah beliau, padahal radio sanggup menyiarkan pekan depan."],["Nilai tiap pilihan",{"A":"narasumber bisa beribadah dengan tenang, pendengar tetap bisa menelepon dan dijawab orang yang tepat, dan radio pun sudah sanggup. Tinggal sepakati harinya.","B":"akalnya bagus: narasumber hadir tanpa mengganggu ibadahnya. Sayangnya rekaman tidak bisa menerima telepon, sedangkan itu separuh acaranya.","E":"bahan tertulis bisa dibacakan siapa saja, pertanyaan pendengar tidak. Yang berhak menjawab soal tarif hanya kepala bidang.","D":"rencana kerja dibuat untuk membantu, bukan untuk memaksa orang meninggalkan ibadahnya, apalagi saat radio menawarkan hari lain.","C":"radio sudah menyanggupi pekan depan. Yang perlu memutuskan justru kamu, bukan mereka."}],["Kunci","A memindahkan acara ke hari yang bisa dihadiri narasumber, karena jawaban beliau tidak tergantikan."],["Analogi","kalau dosen penguji utama berhalangan karena ibadah, sidangnya dijadwal ulang. Tidak diganti asisten, dan tidak diakali dengan video rekaman."],["Jebakan","rekaman sehari sebelumnya tampak cerdik karena semua kebagian: narasumber beribadah, siaran tetap tayang. Ingat separuh acaranya tanya jawab telepon, dan bagian itu yang tidak bisa direkam."],["Tips","di soal tentang hari raya, jawaban terbaik kadang menggeser jadwal, kadang tidak. Fakta kecil di cerita yang memutuskan, misalnya apakah orangnya bisa diganti."]]},{"k":"C","p":{"A":3,"B":1,"C":5,"D":4,"E":2},"b":[["Yang ditanya","pekan lalu rekan senior di tim lapangan BPBD menyodorimu formulir setia kepada kelompok yang ingin mengganti Pancasila. Kamu menolak dan menasihatinya. Kemarin, saat pelatihan relawan, kamu melihat sendiri ia membagikan formulir itu kepada dua relawan muda."],["Nilai tiap pilihan",{"C":"kamu sudah mencoba cara pribadi, dan ternyata ia jalan terus. Sekarang saatnya pimpinan tahu, dengan dua kejadian yang kamu alami dan lihat sendiri.","D":"catatanmu rapi, dan kamu memang berniat melapor. Hanya saja buktinya sudah kamu lihat kemarin. Menunggu ajakan berikutnya berarti menunggu ada relawan lain yang disodori formulir.","A":"nasihat pertama tidak mempan, kenapa yang kedua akan berbeda? Formulir yang dikembalikan relawan juga tidak menghentikan orang yang membagikannya.","E":"kamu menjaga hubungan, ia tetap membagikan formulir. Diam di sini terasa damai, sementara yang didiamkan adalah ajakan mengganti Pancasila.","B":"kebebasan berkeyakinan dilindungi. Mengajak orang setia kepada kelompok yang ingin mengganti Pancasila sudah lain urusannya."}],["Kunci","C menghentikan ajakan lewat pimpinan setelah jalur pribadi terbukti tidak berhasil."],["Analogi","temanmu sudah kamu ingatkan berhenti menyebarkan tautan pinjaman online ilegal, tapi kemarin ia membagikannya lagi ke adik kelas. Kali ini kamu lapor ke guru BK."],["Jebakan","mencatat dan menunggu satu kejadian lagi terdengar teliti. Kata \"melihat sendiri\" di cerita menunjukkan buktinya sudah ada, dan menunggu lebih lama hanya memberi waktu bagi ajakan itu menyebar."],["Tips","melapor bukan berarti mengkhianati rekan, apalagi setelah kamu memberinya kesempatan lewat nasihat."]]},{"k":"B","p":{"A":4,"B":5,"C":3,"D":1,"E":2},"b":[["Yang ditanya","edaran baru mewajibkan pakaian adat setiap Kamis, tapi tidak menyebut adat daerah mana. Kamu staf kepegawaian yang ditugasi menyusun petunjuk pelaksanaannya. Enam pegawai dari luar daerah bertanya apakah boleh memakai pakaian adat asalnya. Pelanggaran edaran ini masuk penilaian disiplin."],["Nilai tiap pilihan",{"B":"kamu sendiri yang menyusun petunjuknya, jadi celah di edaran bisa kamu isi di situ. Begitu tertulis, setiap pegawai tahu pakaian adat asalnya diterima, tanpa takut dinilai melanggar.","A":"semua pegawai jadi tahu, dan budaya mereka dihargai. Tapi pengumuman di grup bukan petunjuk pelaksanaan. Kalau nanti ada yang dinilai melanggar edaran, siapa yang menanggung? Pegawainya sendiri.","C":"enam orang aman. Pegawai luar daerah yang tidak sempat bertanya bagaimana?","E":"suara terbanyak biasanya datang dari pegawai setempat. Yang sedikit justru kehilangan haknya.","D":"menafsirkan edaran bisa jadi urusan bagian hukum, tetapi menyusun petunjuknya tugasmu. Pertanyaan pegawai itu justru bahan untuk tugasmu sendiri."}],["Kunci","B memakai tugas yang ada di tanganmu untuk memberi semua pegawai pegangan yang sama."],["Analogi","seperti aturan seragam sekolah yang menulis jelas jilbab boleh dipakai, sehingga siswi tidak perlu minta izin satu per satu ke guru piket."],["Jebakan","mengumumkan ke semua pegawai terdengar sudah adil. Kalimat \"pelanggaran edaran masuk penilaian disiplin\" membuat pengumuman itu berisiko, karena isi petunjuk yang kamu susun tetap tidak menyebut adat asal."],["Tips","aturan tertulis untuk semua orang lebih adil daripada izin bagi yang kebetulan berani bertanya."]]},{"k":"E","p":{"A":4,"B":2,"C":3,"D":1,"E":5},"b":[["Yang ditanya","kamu petugas pengaduan di RSUD. Ada unggahan dari keluarga pasien: ia dimintai Rp50.000 di kasir rawat jalan supaya klaimnya cepat diproses. Unggahan itu tidak menyebut tanggal maupun nama petugas, sementara kasir dijaga empat orang bergantian. Setiap pembayaran di kasir tercetak di kuitansi bernomor."],["Nilai tiap pilihan",{"E":"dari waktu kejadian dan nomor kuitansi, kamu bisa tahu siapa yang berjaga saat itu. Aduannya ditanggapi, dan petugas lain tidak ikut tercoreng.","A":"kamu bergerak cepat, dan direktur perlu tahu. Bayangkan petugas yang mungkin tidak tahu apa-apa ikut diperiksa hanya karena unggahannya tidak menyebut nama.","C":"pengumuman itu berguna untuk ke depan. Aduan yang sudah ada tetap menggantung.","B":"unggahannya hilang, masalahnya tidak. Pengunggah pun bisa merasa dibungkam.","D":"niatmu menolong, tapi uang pribadimu tidak menghentikan pungutan berikutnya."}],["Kunci","E mencari keterangan yang bisa diperiksa sebelum ada yang disalahkan."],["Analogi","ponselmu hilang di kelas? Guru yang bijak tidak menggeledah seluruh siswa. Ia bertanya dulu kapan terakhir kamu memegangnya dan di mana."],["Jebakan","kata \"keempat\" di pilihan A yang perlu kamu perhatikan. Karena kejadiannya belum jelas, orang yang tidak terlibat ikut diperiksa. Kuitansi bernomor di cerita adalah petunjuk untuk mempersempitnya."],["Tips","sebelum ada yang dihukum, cari bukti yang bisa dicocokkan, seperti nomor kuitansi."]]},{"k":"D","p":{"A":4,"B":1,"C":2,"D":5,"E":3},"b":[["Yang ditanya","dua rekan meneruskan poster ke grup pegawai kantor pajak yang kamu kelola. Isinya: membayar pajak daerah haram karena pemerintah tidak sah. Dalam sejam, puluhan anggota sudah membacanya. Salah satu pengirim lalu bertanya di bawahnya apakah isi poster itu benar."],["Nilai tiap pilihan",{"D":"posternya berhenti beredar, dan kedua rekanmu diajak bicara tanpa ditonton puluhan orang. Rekan yang bertanya pun akhirnya mendapat jawaban.","A":"grup jadi bersih, dan ada aturan yang tersemat. Hanya saja rekan yang bertanya apakah isinya benar tidak pernah mendapat jawaban. Aturan melarang, tapi tidak meluruskan.","E":"posternya ditarik, tapi kedua rekanmu dipermalukan di depan grup. Salah satunya bahkan bertanya apakah isinya benar, tanda ia sendiri ragu.","C":"kepala kantor perlu tahu kalau keadaannya membesar. Menghapus poster sudah ada di tanganmu sebagai admin, jangan menunggu.","B":"puluhan orang sudah membaca dalam sejam. Menunggu ada yang keberatan sama dengan membiarkannya terus menyebar."}],["Kunci","D menghentikan sebarannya, lalu menyelesaikan urusannya dengan kedua pengirim secara pribadi."],["Analogi","temanmu meneruskan pesan berantai hoaks ke grup kelas. Kamu hapus pesannya, lalu mengobrol dengannya berdua, bukan mengumumkan namanya di grup."],["Jebakan","ancaman laporan di pilihan E kedengarannya tegas. Kalimat terakhir cerita mengubah gambarannya: salah satu pengirim bertanya apakah isinya benar. Ia sedang ragu, bukan sedang mengajak."],["Tips","bedakan orang yang menyebarkan karena yakin dari orang yang menyebarkan karena ragu. Caramu menegur ikut berbeda."]]}];
